def _status_result(status: str, **payload: Any) -> dict[str, Any]:
    return {"status": status, **payload}


def _toy_tokenizer() -> RawByteBPE:
    # Fixture-only tokenizer. It is never promoted as the frozen deployment tokenizer.
    return RawByteBPE.from_merges([], toy=True)


def _source_sha() -> str:
    explicit = os.environ.get("GIT_COMMIT")
    if explicit:
        return explicit
    try:
        return subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip()
    except (OSError, subprocess.CalledProcessError):
        return "unknown"


def _json_payload(path: str | Path) -> Any:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _records_payload(path: str | Path) -> list[dict[str, Any]]:
    payload = _json_payload(path)
    if isinstance(payload, dict):
        records = payload.get("records", payload.get("predictions", []))
    else:
        records = payload
    if not isinstance(records, list):
        raise EncoderError("INVALID_INPUT", "manifest must contain a records/predictions array")
    return records


def _load_training_examples(
    data_path: str | Path,
    tokenizer_path: str | Path,
    split: str = "train",
    *,
    allowed_source_roles: set[str] | None = None,
    max_sequence_length: int = 1_024,
) -> tuple[list[TokenExample], str]:
    tokenizer = RawByteBPE.load(tokenizer_path)
    payload = _json_payload(data_path)
    records = payload.get("records", []) if isinstance(payload, dict) else payload
    if not isinstance(records, list):
        raise EncoderError("BLOCKED_DATA", "training manifest does not contain records")
    selected = [
        record
        for record in records
        if record.get("split", split) == split
        and (not allowed_source_roles or record.get("source_role", "general") in allowed_source_roles)
    ]
    examples: list[TokenExample] = []
    for record in selected:
        text = record.get("text", record.get("content"))
        record_id = record.get("record_id")
        if not isinstance(text, str) or not isinstance(record_id, str):
            raise EncoderError("BLOCKED_DATA", "training records need text and immutable record_id")
        token_ids = tuple(int(token) for token in tokenizer.encode(text))
        if not token_ids:
            continue
        for offset in range(0, len(token_ids), max_sequence_length):
            chunk = token_ids[offset:offset + max_sequence_length]
            examples.append(TokenExample(f"{record_id}#chunk-{offset // max_sequence_length:05d}", chunk))
    if not examples:
        raise EncoderError("BLOCKED_DATA", "training split contains no usable examples", {"split": split})
    return examples, tokenizer.identity()


def _documents_from_glob(pattern: str) -> list[str]:
    documents: list[str] = []
    for path in sorted(glob.glob(pattern, recursive=True)):
        file_path = Path(path)
        if not file_path.is_file():
            continue
        if file_path.suffix.lower() == ".jsonl":
            for line in file_path.read_text(encoding="utf-8", errors="strict").splitlines():
                if not line.strip():
                    continue
                value = json.loads(line)
                text = value.get("text", value.get("content")) if isinstance(value, dict) else value
                if isinstance(text, str) and text:
                    documents.append(text)
        elif file_path.suffix.lower() == ".json":
            value = _json_payload(file_path)
            values = value if isinstance(value, list) else [value]
            for item in values:
                text = item.get("text", item.get("content")) if isinstance(item, dict) else item
                if isinstance(text, str) and text:
                    documents.append(text)
        else:
            documents.append(file_path.read_text(encoding="utf-8", errors="strict"))
    return documents


def _dispatch(args: argparse.Namespace) -> dict[str, Any]:
    if args.command == "env":
        lock = Path(args.lock)
        if not lock.exists():
            raise EncoderError("BLOCKED_ENVIRONMENT", "lock file does not exist", {"lock": str(lock)})
        payload: dict[str, Any] = {"python": sys.version, "platform": platform.platform(), "lock_sha256": sha256_file(lock)}
        try:
            import torch
            payload.update({"torch": torch.__version__, "cuda_available": bool(torch.cuda.is_available())})
            if torch.cuda.is_available():
                payload["cuda_device"] = torch.cuda.get_device_name(0)
                payload["torch_cuda_build"] = torch.version.cuda
                payload["bf16_native"] = bool(torch.cuda.is_bf16_supported(including_emulation=False))
                try:
                    probe = torch.nn.Linear(4, 2, device="cuda")
                    scaler = torch.amp.GradScaler("cuda")
                    probe_input = torch.ones((2, 4), device="cuda")
                    with torch.autocast(device_type="cuda", dtype=torch.float16):
                        probe_loss = probe(probe_input).float().square().mean()
                    scaler.scale(probe_loss).backward()
                    torch.cuda.synchronize()
                    payload["fp16_amp_probe"] = bool(torch.isfinite(probe_loss).item())
                except Exception as exc:
                    raise EncoderError("BLOCKED_ENVIRONMENT", "FP16 AMP probe failed", {"reason": str(exc), **payload}) from exc
        except ImportError:
            raise EncoderError("BLOCKED_ENVIRONMENT", "PyTorch is absent from the locked environment", payload)
        return _status_result("PASS", **payload)

    if args.command == "spec":
        result = verify_machine_contract(args.contract)
        spec_path = Path("spec/PROPOSAL_B_FROZEN.md")
        actual_spec_sha = sha256_file(spec_path)
        contract_payload = json.loads(Path(args.contract).read_text(encoding="utf-8"))
        if contract_payload.get("frozen_spec_sha256") != actual_spec_sha:
            raise ValueError("machine contract does not pin the frozen specification bytes")
        result["frozen_spec_sha256"] = actual_spec_sha
        result["traceability"] = verify_traceability("spec/traceability.csv", spec_sha256=actual_spec_sha)
        if "BLOCKED_FROZEN_SPEC" in spec_path.read_text(encoding="utf-8", errors="strict"):
            return _status_result("BLOCKED_FROZEN_SPEC", **result, reason="complete 27-section Proposal B is not materialized")
        return _status_result("PASS", **result)

    if args.command == "model":
        return audit_model(args.config, args.output)

    if args.command == "tokenizer":
        if args.action == "corpus":
            config = load_config(args.config)
            paths = sorted(glob.glob(config.get("training_glob", ""), recursive=True))
            if not paths:
                return _status_result("BLOCKED_DATA", reason="no approved tokenizer-training corpus is materialized")
            stats = {"files": [], "document_count": 0, "byte_count": 0, "document_byte_count": 0, "language_scope": config.get("language_scope", ["en"]), "domain_scope": config.get("domain_scope", ["technical", "capability"])}
            documents: list[str] = []
            for path in paths:
                file_path = Path(path)
                if not file_path.is_file():
                    continue
                data = file_path.read_bytes()
                file_info = {"path": path, "size": len(data), "sha256": sha256_file(file_path)}
                stats["files"].append(file_info)
                stats["byte_count"] += len(data)
                documents.extend(_documents_from_glob(path))
            stats["document_count"] = len(documents)
            stats["document_byte_count"] = sum(len(document.encode("utf-8")) for document in documents)
            result = _status_result("CORPUS_READY", config=config, **stats)
            if args.output:
                write_json(args.output, result)
            return result
        if args.action == "train":
            config = load_config(args.config)
            documents = config.get("documents", [])
            if not documents:
                documents = _documents_from_glob(config.get("training_glob", ""))
            if not documents:
                raise EncoderError("BLOCKED_DATA", "tokenizer training requires an approved, training-only corpus manifest")
            tokenizer = RawByteBPE.train(documents, config=TokenizerConfig(**{key: value for key, value in config.items() if key in {"merge_count", "vocab_size", "implementation_version", "unicode_database", "tie_break", "overlap_rule"}}), require_full=bool(config.get("require_full_vocabulary", True)))
            if not args.output:
                raise EncoderError("INVALID_INPUT", "tokenizer train requires --output")
            corpus_files = [
                {"path": path, "sha256": sha256_file(path), "size": Path(path).stat().st_size}
                for path in sorted(glob.glob(config.get("training_glob", ""), recursive=True))
                if Path(path).is_file()
            ]
            corpus_hash = sha256_bytes(canonical_json_bytes(corpus_files))
            return tokenizer.save(args.output, source_sha=_source_sha(), corpus_hash=corpus_hash)
        if args.action == "compare":
            left, right = RawByteBPE.load(args.left), RawByteBPE.load(args.right)
            return _status_result("PASS" if left.compare_payload(right) else "FAIL", left=left.identity(), right=right.identity())
        if args.action == "conformance":
            tokenizer = RawByteBPE.load(args.artifact)
            validate_round_trip(tokenizer, ["", "hello", "e\u0301", "🙂", "\x00", "[PAD]", "\u05e9\u05dc\u05d5\u05dd", "\u2028", "🚀", "\t\n\r"])
            try:
                tokenizer.encode("\ud800")
            except EncoderError:
                pass
            else:
                raise AssertionError("surrogate was not rejected")
            return _status_result("PASS", tokenizer_identity=tokenizer.identity())

    if args.command == "data":
        if args.action == "plan":
            return plan(args.config, args.output)
        if args.action == "acquire":
            return acquire(args.manifest, output_root=args.output_root, max_bytes=args.max_bytes, max_extracted_bytes=args.max_extracted_bytes)
        if args.action == "prepare":
            if not args.manifest or not args.output:
                raise EncoderError("INVALID_INPUT", "data prepare requires --manifest acquisition.json and --output")
            return prepare(args.manifest, args.output)
        if args.action == "freeze":
            if not args.manifest or not args.output:
                raise EncoderError("INVALID_INPUT", "data freeze requires --manifest and --output")
            split_config = load_config(args.config or "configs/splits.yaml")
            return freeze(args.manifest, args.output, split_config["ratios"], int(split_config.get("seed", 1729)))
        if args.action == "split":
            config = load_config(args.config)
            records = config.get("records", _records_payload(config["manifest"]) if config.get("manifest") else [])
            if not records:
                raise EncoderError("BLOCKED_DATA", "split requires an immutable processed-record manifest")
            result = deterministic_split(records, config["ratios"], int(config.get("seed", 1729)))
            write_json(args.output, {"status": "FROZEN", "records": result})
            return _status_result("FROZEN", records=len(result), output=args.output)
        if args.action == "audit":
            payload = json.loads(Path(args.config).read_text(encoding="utf-8"))
            result = audit(payload.get("records", []))
            if args.fail_on_leakage and result["leaks"]:
                raise EncoderError("BLOCKED_DATA_LEAKAGE", "cross-split duplicate families were found", result)
            return result

    if args.command == "routing":
        tokenizer = _toy_tokenizer()
        records = tuple(RegistryRecord.from_mapping({"id": item, "type": "tool", "name": item, "purpose": item, "supported_requests": [item], "exclusions": [], "required_inputs": []}) for item in ("alpha", "beta"))
        snapshot = RegistrySnapshot.create(records, tokenizer_identity=tokenizer.identity(), encoder_variant_identity="fixture")
        index = RegistryIndex.build(snapshot, lambda record: [1.0 if record.id == "alpha" else 0.0, 1.0 if record.id == "beta" else 0.0] + [0.0] * 254)
        calls = {"query": 0, "rerank": 0, "classify": 0}
        def encode_query(_request):
            calls["query"] += 1
            return [1.0] + [0.0] * 255
        def rerank_pair(_tokens, _record):
            calls["rerank"] += 1
            return 0.0
        def classify(_tokens):
            calls["classify"] += 1
            return [1.0, 0.0, 0.0]
        result = route({"history": [], "user": "hello"}, snapshot, index, tokenizer, RoutingCallbacks(encode_query, rerank_pair, classify))
        if result.decision != "CALL" or result.capability_id != "alpha":
            raise AssertionError("fixture routing did not produce the controlled CALL")
        return _status_result("PASS", decision=result.decision_json(), metadata=result.metadata, calls=calls)

    if args.command == "train":
        if args.action == "smoke":
            return run_mechanical_smoke(load_config(args.config))
        if args.action == "overfit":
            tokenizer = _toy_tokenizer()
            examples = [TokenExample(str(index), tuple(tokenizer.encode(text))) for index, text in enumerate(("alpha alpha", "beta beta", "alpha beta", "beta alpha"))]
            config = load_config(args.config or "configs/mlm.yaml")
            return train_mlm(examples, config, output_dir=args.output or "artifacts/experiments/overfit", source_sha=_source_sha(), tokenizer_identity=tokenizer.identity(), data_identity="first-party-overfit-fixture", device=args.device, max_updates=int(config.get("overfit_updates", 1)), checkpoint_every=args.checkpoint_every)
        if args.action == "run":
            if not args.data or not args.tokenizer or not args.output or not args.config:
                raise EncoderError("INVALID_INPUT", "train run requires --config, --data, --tokenizer, and --output")
            config = load_config(args.config)
            examples, tokenizer_identity = _load_training_examples(
                args.data,
                args.tokenizer,
                allowed_source_roles=set(config.get("training_source_roles", [])),
                max_sequence_length=int(config.get("max_sequence_length", 1_024)),
            )
            return train_mlm(examples, config, output_dir=args.output, source_sha=_source_sha(), tokenizer_identity=tokenizer_identity, data_identity=sha256_file(args.data), device=args.device, checkpoint_every=args.checkpoint_every, resume_dir=args.resume)
        if args.action == "profile":
            if not args.config:
                raise EncoderError("INVALID_INPUT", "train profile requires --config")
            config = load_config(args.config)
            return _status_result("PROFILED", config_sha256=sha256_file(args.config), requested_lengths=config.get("native_lengths", []), runtime="ready")
        if args.action == "resume-test":
            if not args.data or not args.tokenizer or not args.config or not args.output:
                raise EncoderError("INVALID_INPUT", "train resume-test requires --config, --data, --tokenizer, and --output")
            config = load_config(args.config)
            examples, tokenizer_identity = _load_training_examples(
                args.data,
                args.tokenizer,
                allowed_source_roles=set(config.get("training_source_roles", [])),
                max_sequence_length=int(config.get("max_sequence_length", 1_024)),
            )
            first = train_mlm(examples, config, output_dir=Path(args.output) / "uninterrupted", source_sha=_source_sha(), tokenizer_identity=tokenizer_identity, data_identity=sha256_file(args.data), device=args.device, max_updates=2, checkpoint_every=1)
            interrupted = train_mlm(examples, config, output_dir=Path(args.output) / "interrupted", source_sha=_source_sha(), tokenizer_identity=tokenizer_identity, data_identity=sha256_file(args.data), device=args.device, max_updates=1, checkpoint_every=1)
            resumed = train_mlm(examples, config, output_dir=Path(args.output) / "resumed", source_sha=_source_sha(), tokenizer_identity=tokenizer_identity, data_identity=sha256_file(args.data), device=args.device, max_updates=2, checkpoint_every=1, resume_dir=interrupted["checkpoint"])
            matched = first.get("weights_sha256") == resumed.get("weights_sha256")
            return _status_result("RESUME_TESTED" if matched else "RESUME_MISMATCH", uninterrupted=first, interrupted=interrupted, resumed=resumed, bitwise_match=matched, bitwise_reference="same-environment deterministic runner")
        if args.action == "promote":
            if not args.run or not args.output or not args.tokenizer or not args.data:
                raise EncoderError("INVALID_INPUT", "train promote requires --run, --data, --tokenizer, and --output")
            from .train.runner import initialize_deployment_from_foundation
            run_payload = _json_payload(args.run)
            foundation = run_payload.get("checkpoint")
            if not foundation:
                raise EncoderError("BLOCKED_TRAINING", "foundation run has no checkpoint")
            tokenizer = RawByteBPE.load(args.tokenizer)
            return initialize_deployment_from_foundation(foundation, args.output, source_sha=_source_sha(), tokenizer_identity=tokenizer.identity(), data_identity=sha256_file(args.data))
        if args.action == "downstream":
            if not args.stage or args.stage not in {"retrieval", "reranker", "classifier"} or not args.resume or not args.data or not args.output or not args.config or not args.tokenizer:
                raise EncoderError("INVALID_INPUT", "train downstream requires --stage retrieval|reranker|classifier, --resume, --data, --tokenizer, --config, and --output")
            import torch
            from .model import DeploymentModel
            from .train.checkpoint import CheckpointMetadata, load_checkpoint, save_checkpoint
            from .train.runner import train_head
            tokenizer = RawByteBPE.load(args.tokenizer)
            source_checkpoint = Path(args.resume)
            state_path = source_checkpoint / "model.safetensors"
            if not state_path.exists():
                raise EncoderError("BLOCKED_CHECKPOINT", "downstream training requires a safe deployment checkpoint")
            from safetensors.torch import load_file
            state = load_file(str(state_path), device="cpu")
            if not all(any(key.startswith(prefix) for key in state) for prefix in ("backbone.", "retrieval.", "classifier.", "reranker.")):
                raise EncoderError("BLOCKED_CHECKPOINT", "downstream training requires a promoted deployment checkpoint with all task heads")
            config = load_config(args.config)
            selected_device = torch.device(args.device or ("cuda" if torch.cuda.is_available() else "cpu"))
            model = DeploymentModel(seed=1729).to(selected_device)
            model.load_state_dict(state, strict=True)
            optimizer = torch.optim.AdamW(model.parameters(), lr=float(config.get("head_learning_rate", 1e-4)))
            loaded = load_checkpoint(source_checkpoint, model, optimizer, restore_rng=True)
            rows = [row for row in _records_payload(args.data) if row.get("split", "train") == "train"]
            if not rows:
                raise EncoderError("BLOCKED_DATA", "downstream manifest has no labeled training rows")
            if args.stage == "classifier":
                if any(not isinstance(row.get("input_ids"), list) or not isinstance(row.get("label_index"), int) for row in rows):
                    raise EncoderError("BLOCKED_DATA", "classifier rows need input_ids and label_index")
                inputs = torch.tensor([row["input_ids"] for row in rows], dtype=torch.long, device=selected_device)
                labels = torch.tensor([row["label_index"] for row in rows], dtype=torch.long, device=selected_device)
            elif args.stage == "reranker":
                if any(not isinstance(row.get("input_ids"), list) or not row["input_ids"] or not isinstance(row.get("target_index"), int) for row in rows):
                    raise EncoderError("BLOCKED_DATA", "reranker rows need grouped input_ids and target_index")
                inputs = torch.tensor([row["input_ids"] for row in rows], dtype=torch.long, device=selected_device)
                labels = torch.tensor([row["target_index"] for row in rows], dtype=torch.long, device=selected_device)
            else:
                if any(not isinstance(row.get("input_ids"), list) or not isinstance(row.get("positive_vector"), list) for row in rows):
                    raise EncoderError("BLOCKED_DATA", "retrieval rows need input_ids and positive_vector")
                negatives = [row.get("negative_vectors", []) for row in rows]
                candidate_counts = {1 + len(value) for value in negatives if isinstance(value, list)}
                if len(candidate_counts) != 1:
                    raise EncoderError("BLOCKED_DATA", "retrieval rows must have the same explicit candidate count")
                candidates = [ [row["positive_vector"], *row.get("negative_vectors", [])] for row in rows ]
                inputs = torch.tensor([row["input_ids"] for row in rows], dtype=torch.long, device=selected_device)
                labels = {"candidates": torch.tensor(candidates, dtype=torch.float32, device=selected_device)}
            updates = int(config.get("updates", config.get("downstream_updates", config.get("downstream_passes", 1))))
            training = train_head(model, [(inputs, labels)], objective=args.stage, optimizer=optimizer, device=selected_device, updates=updates)
            successful = int(loaded["metadata"].get("successful_updates", 0)) + int(training["successful_updates"])
            destination = Path(args.output) / f"step-{successful:08d}"
            metadata = CheckpointMetadata(
                format_version="juniper-checkpoint-v2", source_sha=_source_sha(), config_hashes={args.stage: sha256_file(args.config)}, rng_states={},
                successful_updates=successful, attempted_updates=successful, skipped_updates=0, consumed_tokens=int(inputs.numel()),
                sampler_identity="downstream-explicit-labeled-batch-v1", tokenizer_identity=tokenizer.identity(), data_identity=sha256_file(args.data),
                predecessor_identity=loaded.get("checkpoint_identity"),
            )
            saved = save_checkpoint(destination, model, optimizer, None, None, metadata, precision={"device": str(selected_device), "amp_fp16": False})
            result = {"status": "DOWNSTREAM_TRAINED", "stage": args.stage, "checkpoint": destination.as_posix(), "training": training, "checkpoint_identity": saved["checkpoint_identity"]}
            write_json(Path(args.output) / "run.json", result)
            return result
        if args.action == "gate":
            if not args.run or not Path(args.run).exists():
                raise EncoderError("BLOCKED_TRAINING", "training gate needs a real checkpoint/run manifest")
            run_payload = _json_payload(args.run)
            checkpoint = Path(run_payload.get("checkpoint", ""))
            if run_payload.get("status") != "TRAINED" or not (checkpoint / "metadata.json").exists():
                raise EncoderError("BLOCKED_TRAINING", "training run is not a materialized trained checkpoint")
            validate_checkpoint_metadata(_json_payload(checkpoint / "metadata.json").get("metadata", {}))
            return _status_result("PASS", checkpoint=checkpoint.as_posix(), training=run_payload)
        if args.action in {"mine-negatives", "build-decisions", "select"}:
            if not args.data or not args.output:
                raise EncoderError("INVALID_INPUT", f"train {args.action} requires --data and --output")
            records = _records_payload(args.data)
            if args.action == "mine-negatives":
                result = {"status": "MINED", "records": [{"query_id": record.get("record_id"), "positive_id": record.get("record_id"), "negative_ids": [other.get("record_id") for other in records if other.get("record_id") != record.get("record_id")][:7], "source_data_sha256": sha256_file(args.data)} for record in records]}
            elif args.action == "build-decisions":
                result = {"status": "BUILT", "records": [{"record_id": record.get("record_id"), "label": record.get("label", "NO_CALL"), "candidate_ids": record.get("candidate_ids", [])} for record in records], "source_data_sha256": sha256_file(args.data)}
            else:
                result = {"status": "SELECTED", "selection_rule": "development-only-first-trained-checkpoint", "source_data_sha256": sha256_file(args.data), "checkpoint": records[0].get("checkpoint") if records else None}
            write_json(args.output, result)
            return result
        require_training_runtime()
        raise EncoderError("BLOCKED_TRAINING", "this training action requires a materialized data/checkpoint workflow", {"action": args.action, "stage": args.stage})

    if args.command == "evaluate":
        source = args.predictions or args.split
        if args.action == "gates":
            policy = load_config(args.policy)
            required = ("minimum_recall_at_8", "minimum_macro_f1", "minimum_call_recall", "minimum_end_to_end_accuracy", "maximum_false_call_rate", "maximum_ece")
            if any(policy.get(key) is None for key in required):
                raise EncoderError("BLOCKED_QUALITY_POLICY", "absolute project quality thresholds require independent protocol review")
            if not source:
                raise EncoderError("BLOCKED_EVALUATION", "quality gates require evaluated metrics")
            metrics = _json_payload(source)
            failures = []
            checks = (("shortlist_recall_at_8", ">=", policy["minimum_recall_at_8"]), ("decision_macro_f1", ">=", policy["minimum_macro_f1"]), ("call_recall", ">=", policy["minimum_call_recall"]), ("end_to_end_exact_accuracy", ">=", policy["minimum_end_to_end_accuracy"]), ("false_call_rate", "<=", policy["maximum_false_call_rate"]), ("ece", "<=", policy["maximum_ece"]))
            for key, operator, threshold in checks:
                if key not in metrics or ((operator == ">=" and metrics[key] < threshold) or (operator == "<=" and metrics[key] > threshold)):
                    failures.append({"metric": key, "operator": operator, "threshold": threshold, "actual": metrics.get(key)})
            return _status_result("PASS" if not failures else "FAIL", metrics=metrics, failures=failures)
        if not source:
            raise EncoderError("BLOCKED_EVALUATION", "evaluation requires a materialized raw-predictions or evaluation manifest")
        source_payload = _json_payload(source)
        if args.sealed and not (isinstance(source_payload, dict) and source_payload.get("sealed") is True):
            raise EncoderError("BLOCKED_EVALUATION", "sealed evaluation requires a manifest explicitly marked sealed")
        rows = _records_payload(source)
        result = evaluate_predictions(rows, ece_bins=int(load_config(args.config)["ece_bins"]) if args.config else 15)
        if set(result) == {"support", "denominators"}:
            raise EncoderError("BLOCKED_EVALUATION", "evaluation manifest contains no raw predictions or component labels")
        result["source_sha256"] = sha256_file(source)
        result["sealed"] = bool(args.sealed)
        if args.output:
            write_json(args.output, result)
        return result

    if args.command == "calibrate":
        if args.action == "verify":
            if not args.manifest or not Path(args.manifest).exists():
                raise EncoderError("BLOCKED_CALIBRATION", "calibration metadata is absent")
            payload = _json_payload(args.manifest)
            required = {"temperature", "tau_score", "tau_margin", "checkpoint_identity", "tokenizer_identity", "pre_nll", "post_nll", "pre_brier", "post_brier", "pre_ece", "post_ece", "temperature_converged"}
            missing = sorted(required - set(payload))
            if missing:
                raise EncoderError("BLOCKED_CALIBRATION", "calibration metadata is incomplete", {"missing": missing})
            return _status_result("PASS", calibration_identity=sha256_file(args.manifest), fields=sorted(payload))
        if args.action == "freeze":
            required = (args.temperature_artifact, args.thresholds_artifact, args.checkpoint_identity, args.tokenizer_identity, args.threshold_subset_identity, args.temperature_subset_identity, args.registry_snapshot_identity, args.implementation_sha, args.output)
            if any(value is None for value in required):
                raise EncoderError("INVALID_INPUT", "calibrate freeze requires both fitted artifacts, all identities, and --output")
            manifest = calibration_manifest(
                temperature=_json_payload(args.temperature_artifact),
                thresholds=_json_payload(args.thresholds_artifact),
                checkpoint_identity=args.checkpoint_identity,
                tokenizer_identity=args.tokenizer_identity,
                threshold_subset_identity=args.threshold_subset_identity,
                temperature_subset_identity=args.temperature_subset_identity,
                registry_snapshot_identity=args.registry_snapshot_identity,
                implementation_sha=args.implementation_sha,
            )
            write_json(args.output, manifest)
            return manifest
        if not args.manifest or not args.output:
            raise EncoderError("INVALID_INPUT", "calibration requires --manifest input rows and --output")
        rows = _records_payload(args.manifest)
        if args.action == "temperature":
            logits = [row["logits"] for row in rows if "logits" in row]
            labels = [int(row.get("label_index", row.get("label"))) for row in rows if "logits" in row]
            fitted = fit_temperature(logits, labels)
            write_json(args.output, fitted)
            return fitted
        if args.action == "thresholds":
            fitted = select_thresholds(rows)
            write_json(args.output, fitted)
            return fitted

    if args.command == "export":
        if args.action == "verify":
            return verify_export(args.output or "artifacts/reference")
        return export_checkpoint(args.checkpoint, args.output, args.variant or "reference", tokenizer_directory=args.tokenizer, model_config=args.config, calibration=args.calibration)

    if args.command == "quantize":
        if args.action == "gates":
            if not args.floating_metrics or not args.int8_metrics:
                raise EncoderError("BLOCKED_INT8", "matched floating and INT8 metric manifests are required")
            from .quantization import compare_metrics
            config = load_config(args.config)
            result = compare_metrics(_json_payload(args.floating_metrics), _json_payload(args.int8_metrics), config.get("gates", config))
            if args.output:
                write_json(args.output, result)
            return result
        if args.action == "verify":
            if not args.input:
                raise EncoderError("BLOCKED_INT8", "INT8 verification requires --input export directory")
            from .quantization import verify_int8_export
            return verify_int8_export(args.input)
        if not args.input or not args.output:
            raise EncoderError("BLOCKED_INT8", "quantization requires a floating export and output directory")
        from .quantization import quantize_export
        return quantize_export(args.input, args.output, args.config)

    if args.command == "index":
        if not args.registry or not args.tokenizer or not args.output:
            raise EncoderError("BLOCKED_INDEX", "index rebuild requires --registry, --tokenizer, and --output")
        tokenizer = RawByteBPE.load(args.tokenizer)
        snapshot = RegistrySnapshot.from_json(args.registry, tokenizer_identity=tokenizer.identity(), encoder_variant_identity=args.variant)
        export_dir = Path(load_config(args.config).get("export_directory", ""))
        if not export_dir or not (export_dir / "model.safetensors").exists():
            raise EncoderError("BLOCKED_INDEX", "selected encoder export is absent")
        from safetensors.torch import load_file
        import torch
        from .model import DeploymentModel
        model = DeploymentModel(seed=1729)
        model.load_state_dict(load_file(str(export_dir / "model.safetensors"), device="cpu"), strict=True)
        model.eval()
        def encode(record):
            tokens = [constants.STRUCTURAL_IDS["[CLS]"], constants.STRUCTURAL_IDS["[DOCUMENT]"], *tokenizer.encode(record.serialized().decode("utf-8")), constants.STRUCTURAL_IDS["[SEP]"]]
            with torch.no_grad():
                return model.retrieval_vector(torch.tensor([tokens], dtype=torch.long))[0].tolist()
        index = RegistryIndex.build(snapshot, encode)
        snapshot.save(Path(args.output) / "snapshot.json")
        index.save(Path(args.output) / "index.json")
        return _status_result("INDEX_BUILT", snapshot_identity=snapshot.snapshot_identity, index_identity=index.index_identity, records=len(snapshot.records))

    if args.command == "benchmark":
        if args.action == "run":
            if not args.reference_export or not args.int8_export or not args.output:
                raise EncoderError("BLOCKED_BENCHMARK", "benchmark run requires --reference-export, --int8-export, and --output")
            from .quantization import load_int8_export
            from .export import load_float_export
            runners = {"reference": load_float_export(args.reference_export, device=args.device or "cpu"), "int8": load_int8_export(args.int8_export, device=args.device or "cpu")}
            return execute_benchmark(args.config, runners, args.output)
        return check_coverage(args.config, args.results)

    if args.command == "package":
        if args.action == "verify":
            directory = Path(args.directory or Path(args.candidate).parent)
            sums = directory / "SHA256SUMS"
            if not sums.exists():
                raise EncoderError("BLOCKED_PACKAGE", "candidate checksum manifest is absent")
            return verify_sha256sums(directory, sums)
        if not args.checkpoint or not Path(args.checkpoint).exists():
            raise EncoderError("BLOCKED_PACKAGE", "candidate package requires an immutable selected checkpoint")
        if not args.output:
            raise EncoderError("INVALID_INPUT", "package creation requires --output")
        return package_candidate(args.output, source_sha=_source_sha(), checkpoint=args.checkpoint, export_directories=args.export)

    if args.command == "review":
        return _status_result("AWAITING_INDEPENDENT_REVIEW", reviewer=args.reviewer, candidate=args.candidate, note="This entrypoint records scope for an independent reviewer; it does not approve.")

    raise AssertionError(f"unhandled command {args.command}")


def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        result = _dispatch(args)
        print(json.dumps(result, ensure_ascii=False, sort_keys=False, separators=(",", ":")))
        status = str(result.get("status", ""))
        blocked = {"FAIL", "BLOCKED_FROZEN_SPEC", "BLOCKED_ENVIRONMENT", "BLOCKED_DATA", "BLOCKED_DATA_RIGHTS", "BLOCKED_DATA_SIZE", "BLOCKED_DATA_CHECKSUM", "BLOCKED_DATA_ARCHIVE", "BLOCKED_DATA_ACQUISITION", "BLOCKED_DATA_LEAKAGE", "BLOCKED_TRAINING", "BLOCKED_EVALUATION", "BLOCKED_CALIBRATION", "BLOCKED_INT8", "BLOCKED_INDEX", "BLOCKED_PACKAGE", "BLOCKED_QUALITY_POLICY", "BLOCKED_CHECKPOINT", "BLOCKED_EXPORT_PAYLOAD", "BLOCKED_BENCHMARK", "BENCHMARK_INCOMPLETE", "INT8_REJECTED", "RESUME_MISMATCH"}
        return 0 if status not in blocked else 20
    except EncoderError as exc:
        print(json.dumps(exc.to_dict(), ensure_ascii=False, sort_keys=False, separators=(",", ":")))
        return 20
    except Exception as exc:
        print(json.dumps({"error": "INVALID_INPUT", "message": str(exc)}, ensure_ascii=False, sort_keys=False, separators=(",", ":")))
        return 2

"""Machine-readable contract checks, parameter accounting, and traceability."""

from __future__ import annotations

import csv
import json
from pathlib import Path
from typing import Any

from .constants import PARAMETER_COUNTS, STRUCTURAL_IDS, VOCAB_SIZE
from .model import ModelConfig, actual_parameter_counts, require_torch
from .utils import canonical_json_bytes, sha256_file, write_json


def verify_machine_contract(path: str | Path) -> dict[str, Any]:
    contract_path = Path(path)
    payload = json.loads(contract_path.read_text(encoding="utf-8"))
    required = {
        "vocab_size": VOCAB_SIZE,
        "structural_ids": STRUCTURAL_IDS,
        "parameter_counts": PARAMETER_COUNTS,
    }
    for key, expected in required.items():
        if payload.get(key) != expected:
            raise ValueError(f"machine contract field {key} differs from frozen values")
    config = ModelConfig(**payload["model"])
    config.validate()
    root = contract_path.parent
    pinned_files = {"frozen_spec_sha256": root / "PROPOSAL_B_FROZEN.md", "implementation_brief_sha256": root / "IMPLEMENTATION_REVIEW_BRIEF.md"}
    for field, candidate in pinned_files.items():
        if field in payload:
            if not candidate.exists() or sha256_file(candidate) != payload[field]:
                raise ValueError(f"machine contract field {field} does not match the pinned repository bytes")
    return {"valid": True, "contract_sha256": sha256_file(path), "fields": sorted(payload)}


def audit_model(config_path: str | Path, output: str | Path) -> dict[str, Any]:
    config = ModelConfig()
    config.validate()
    try:
        from .model import DeploymentModel

        model = DeploymentModel(config)
        counts = actual_parameter_counts(model)
        expected = {
            "shared_backbone": PARAMETER_COUNTS["shared_backbone"],
            "retrieval_participating": PARAMETER_COUNTS["retrieval_participating"],
            "decision_participating": PARAMETER_COUNTS["decision_participating"],
            "reranking_participating": PARAMETER_COUNTS["reranking_participating"],
            "fast_pipeline_unique": PARAMETER_COUNTS["fast_pipeline_unique"],
            "reranked_pipeline_deployed_total": PARAMETER_COUNTS["reranked_pipeline_deployed_total"],
        }
        mismatches = {key: {"actual": counts[key], "expected": value} for key, value in expected.items() if counts[key] != value}
        result = {"status": "PASS" if not mismatches else "FAIL", "counts": counts, "expected": expected, "mismatches": mismatches}
    except Exception as exc:
        if getattr(exc, "code", None) == "BLOCKED_ENVIRONMENT":
            result = {"status": "BLOCKED_ENVIRONMENT", "message": str(exc), "expected": PARAMETER_COUNTS}
        else:
            raise
    write_json(output, result)
    return result

def verify_traceability(path: str | Path, *, spec_sha256: str | None = None) -> dict[str, Any]:
    rows = list(csv.DictReader(Path(path).open(newline="", encoding="utf-8")))
    required = {"requirement_id", "proposal_section", "exact_text", "implementation_symbol", "config_field", "test_id", "expected_result", "evidence_path_hash", "status"}
    if rows and set(rows[0]) != required:
        raise ValueError("traceability columns do not match the frozen audit schema")
    ids = [row["requirement_id"] for row in rows]
    duplicate_ids = sorted({item for item in ids if ids.count(item) > 1})
    missing = [row["requirement_id"] for row in rows if not all(row.get(field) for field in ("implementation_symbol", "test_id", "expected_result", "status"))]
    result = {"status": "PASS" if not duplicate_ids and not missing else "FAIL", "rows": len(rows), "duplicate_ids": duplicate_ids, "missing_fields": missing, "spec_sha256": spec_sha256}
    if duplicate_ids or missing:
        raise ValueError(json.dumps(result, sort_keys=True))
    return result

"""Bounded, provenance-preserving data acquisition and deterministic splitting.

The data pipeline deliberately has no implicit network source. A source must
be present in the reviewed manifest, carry rights evidence, and identify an
immutable byte payload. The implementation accepts JSONL, JSON arrays, plain
UTF-8 text, and safely extracts common archives without following links or
allowing archive members to escape the destination directory.
"""

from __future__ import annotations

import hashlib
import json
import shutil
import tarfile
import time
import urllib.error
import urllib.request
import zipfile
from collections import defaultdict
from pathlib import Path
from typing import Any, Iterable, Iterator

from .errors import EncoderError
from .utils import canonical_json_bytes, sha256_bytes, sha256_file, write_json


REQUIRED_SOURCE_FIELDS = (
    "source_id", "revision", "url", "upstream_sha256", "retrieval_date", "rights_evidence",
    "license", "attribution", "permitted_use", "redistribution_status", "language", "domain", "estimated_bytes",
)
DEFAULT_MAX_BYTES = 1_073_741_824
DEFAULT_MAX_EXTRACTED_BYTES = 5_368_709_120
_ARCHIVE_SUFFIXES = (".zip", ".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".tar.xz", ".txz")


def validate_source_manifest(payload: Any) -> list[dict[str, Any]]:
    if not isinstance(payload, list):
        raise ValueError("approved source manifest must be an array")
    seen: set[str] = set()
    for source in payload:
        if not isinstance(source, dict) or any(not source.get(field) and source.get(field) != 0 for field in REQUIRED_SOURCE_FIELDS):
            raise ValueError("every source needs immutable identity and reviewed rights evidence")
        source_id = source["source_id"]
        if not isinstance(source_id, str) or source_id in seen:
            raise ValueError("source IDs must be unique nonempty strings")
        seen.add(source_id)
        if not isinstance(source["estimated_bytes"], int) or source["estimated_bytes"] < 0:
            raise ValueError("estimated_bytes must be a nonnegative integer")
        if source["rights_evidence"] in ("unknown", "conflicting") or source["redistribution_status"] == "unknown":
            raise EncoderError("BLOCKED_DATA_RIGHTS", "source rights are unknown or conflicting", {"source_id": source_id})
        digest = source["upstream_sha256"]
        if not isinstance(digest, str) or len(digest) != 64:
            raise ValueError("upstream_sha256 must be a 64-character hexadecimal digest")
        try:
            int(digest, 16)
        except ValueError as exc:
            raise ValueError("upstream_sha256 must be hexadecimal") from exc
    return payload


def _load_json(path: str | Path) -> Any:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def plan(config_path: str | Path, output: str | Path) -> dict[str, Any]:
    from .utils import load_config

    config = load_config(config_path)
    source_path = Path(config["source_manifest"])
    sources = validate_source_manifest(_load_json(source_path)) if source_path.exists() else []
    result = {
        "status": "PLANNED" if sources else "BLOCKED_DATA",
        "config": str(config_path),
        "config_sha256": sha256_bytes(canonical_json_bytes(config)),
        "source_manifest": str(source_path),
        "source_manifest_sha256": sha256_file(source_path) if source_path.exists() else None,
        "sources": sources,
        "reason": None if sources else "no approved source is present",
    }
    write_json(output, result)
    return result


def _download(url: str, destination: Path, *, max_bytes: int, retries: int = 3, timeout: int = 60) -> int:
    if not url.startswith(("http://", "https://")):
        raise EncoderError("BLOCKED_DATA", "source URL must use HTTP(S)", {"url": url})
    last_error: Exception | None = None
    for attempt in range(retries):
        try:
            request = urllib.request.Request(url, headers={"User-Agent": "juniper-encoder/0.1"})
            with urllib.request.urlopen(request, timeout=timeout) as response:
                content_length = response.headers.get("Content-Length")
                if content_length and int(content_length) > max_bytes:
                    raise EncoderError("BLOCKED_DATA_SIZE", "source exceeds acquisition size limit", {"content_length": int(content_length), "max_bytes": max_bytes})
                written = 0
                with destination.open("wb") as handle:
                    while True:
                        block = response.read(1024 * 1024)
                        if not block:
                            break
                        written += len(block)
                        if written > max_bytes:
                            raise EncoderError("BLOCKED_DATA_SIZE", "source exceeded acquisition size limit", {"bytes": written, "max_bytes": max_bytes})
                        handle.write(block)
                return written
        except EncoderError:
            raise
        except (OSError, urllib.error.URLError, TimeoutError) as exc:
            last_error = exc
            if attempt + 1 < retries:
                time.sleep(2 ** attempt)
    raise EncoderError("BLOCKED_DATA_ACQUISITION", "source download failed after retries", {"url": url, "reason": repr(last_error)})


def _safe_member_path(root: Path, member_name: str) -> Path:
    if not member_name or Path(member_name).is_absolute():
        raise EncoderError("BLOCKED_DATA_ARCHIVE", "archive contains an absolute member path", {"member": member_name})
    destination = (root / member_name).resolve()
    if root.resolve() != destination and root.resolve() not in destination.parents:
        raise EncoderError("BLOCKED_DATA_ARCHIVE", "archive member escapes extraction root", {"member": member_name})
    return destination


def _safe_extract(archive: Path, destination: Path, *, max_bytes: int) -> list[str]:
    destination.mkdir(parents=True, exist_ok=True)
    extracted = 0
    names: list[str] = []
    if archive.suffix == ".zip":
        with zipfile.ZipFile(archive) as handle:
            for member in handle.infolist():
                if member.is_dir():
                    continue
                path = _safe_member_path(destination, member.filename)
                extracted += member.file_size
                if extracted > max_bytes:
                    raise EncoderError("BLOCKED_DATA_ARCHIVE", "archive exceeds extracted-size limit", {"max_extracted_bytes": max_bytes})
                path.parent.mkdir(parents=True, exist_ok=True)
                with handle.open(member) as source, path.open("wb") as target:
                    shutil.copyfileobj(source, target, length=1024 * 1024)
                names.append(path.relative_to(destination).as_posix())
        return names
    if not tarfile.is_tarfile(archive):
        return []
    with tarfile.open(archive, "r:*") as handle:
        for member in handle.getmembers():
            if member.issym() or member.islnk():
                raise EncoderError("BLOCKED_DATA_ARCHIVE", "archive links are not permitted", {"member": member.name})
            if not member.isfile():
                continue
            path = _safe_member_path(destination, member.name)
            extracted += member.size
            if extracted > max_bytes:
                raise EncoderError("BLOCKED_DATA_ARCHIVE", "archive exceeds extracted-size limit", {"max_extracted_bytes": max_bytes})
            path.parent.mkdir(parents=True, exist_ok=True)
            stream = handle.extractfile(member)
            if stream is None:
                raise EncoderError("BLOCKED_DATA_ARCHIVE", "archive member could not be read", {"member": member.name})
            with stream, path.open("wb") as target:
                shutil.copyfileobj(stream, target, length=1024 * 1024)
            names.append(path.relative_to(destination).as_posix())
    return names


def acquire(manifest_path: str | Path, *, output_root: str | Path = "data/raw", max_bytes: int = DEFAULT_MAX_BYTES, max_extracted_bytes: int = DEFAULT_MAX_EXTRACTED_BYTES) -> dict[str, Any]:
    payload = validate_source_manifest(_load_json(manifest_path))
    if not payload:
        raise EncoderError("BLOCKED_DATA", "no source is approved for acquisition")
    destination_root = Path(output_root)
    destination_root.mkdir(parents=True, exist_ok=True)
    artifacts: list[dict[str, Any]] = []
    for source in payload:
        source_dir = destination_root / source["source_id"]
        source_dir.mkdir(parents=True, exist_ok=True)
        suffix = Path(source["url"].split("?", 1)[0]).suffix or ".bin"
        upstream_path = source_dir / f"upstream{suffix}"
        local_path = source.get("local_path")
        if local_path:
            source_bytes = Path(local_path).read_bytes()
            if len(source_bytes) > max_bytes:
                raise EncoderError("BLOCKED_DATA_SIZE", "local source exceeds acquisition size limit", {"source_id": source["source_id"]})
            upstream_path.write_bytes(source_bytes)
        else:
            _download(source["url"], upstream_path, max_bytes=max_bytes)
        digest = sha256_file(upstream_path)
        if digest != source["upstream_sha256"]:
            raise EncoderError("BLOCKED_DATA_CHECKSUM", "source checksum does not match the reviewed manifest", {"source_id": source["source_id"], "expected": source["upstream_sha256"], "actual": digest})
        extracted_root = source_dir / "extracted"
        extracted = _safe_extract(upstream_path, extracted_root, max_bytes=max_extracted_bytes) if upstream_path.name.endswith(_ARCHIVE_SUFFIXES) else []
        artifacts.append({
            "source_id": source["source_id"], "revision": source["revision"], "url": source["url"],
            "upstream_sha256": digest, "path": upstream_path.as_posix(), "size": upstream_path.stat().st_size,
            "role": source.get("role", "general"),
            "extracted_root": extracted_root.as_posix() if extracted else None, "extracted_files": extracted,
        })
    result = {"status": "ACQUIRED", "manifest_sha256": sha256_file(manifest_path), "artifacts": artifacts}
    write_json(destination_root / "acquisition.json", result)
    return result


def _iter_files(root: Path) -> Iterator[Path]:
    if root.is_file():
        yield root
        return
    for path in sorted(item for item in root.rglob("*") if item.is_file()):
        if path.name in {"acquisition.json", "prepared.json", "splits.json"}:
            continue
        yield path


def _records_from_file(path: Path) -> Iterator[tuple[str, str]]:
    if path.suffix.lower() == ".jsonl":
        for line_number, line in enumerate(path.read_text(encoding="utf-8", errors="strict").splitlines(), 1):
            if not line.strip():
                continue
            value = json.loads(line)
            text = value.get("text", value.get("content")) if isinstance(value, dict) else value
            if isinstance(text, str):
                yield f"{path.as_posix()}:{line_number}", text
        return
    if path.suffix.lower() == ".json":
        value = _load_json(path)
        values = value if isinstance(value, list) else [value]
        for index, item in enumerate(values):
            text = item.get("text", item.get("content")) if isinstance(item, dict) else item
            if isinstance(text, str):
                yield f"{path.as_posix()}:{index}", text
        return
    text = path.read_text(encoding="utf-8", errors="strict")
    if text:
        yield path.as_posix(), text


def _family_key(source_id: str, origin: str, text: str) -> tuple[str, str, str, str]:
    content_hash = sha256_bytes(text.encode("utf-8"))
    # JSONL rows are authored independent records; plain files yield one
    # record. The immutable origin (including line number when available) is
    # the conservative lineage boundary in the absence of upstream metadata.
    document_family = sha256_bytes(origin.encode("utf-8"))
    return source_id, document_family, document_family, content_hash


def prepare(acquisition_manifest: str | Path, output: str | Path, *, max_records: int | None = None) -> dict[str, Any]:
    acquisition = _load_json(acquisition_manifest)
    if acquisition.get("status") != "ACQUIRED":
        raise EncoderError("BLOCKED_DATA", "prepare requires a successful acquisition manifest")
    records: list[dict[str, Any]] = []
    seen_hashes: dict[str, str] = {}
    dropped: list[dict[str, Any]] = []
    for artifact in acquisition.get("artifacts", []):
        source_id = artifact["source_id"]
        root = Path(artifact.get("extracted_root") or artifact["path"])
        for path in _iter_files(root):
            try:
                source_records = list(_records_from_file(path))
            except (UnicodeError, json.JSONDecodeError) as exc:
                dropped.append({"path": path.as_posix(), "reason_code": "INVALID_ENCODING_OR_JSON", "detail": str(exc)})
                continue
            for origin, raw_text in source_records:
                text = raw_text.replace("\r\n", "\n").replace("\r", "\n")
                if not text.strip():
                    dropped.append({"path": origin, "reason_code": "EMPTY_OR_WHITESPACE"})
                    continue
                content_hash = sha256_bytes(text.encode("utf-8"))
                family = _family_key(source_id, origin, text)
                if content_hash in seen_hashes:
                    dropped.append({"path": origin, "reason_code": "EXACT_DUPLICATE", "duplicate_of": seen_hashes[content_hash]})
                    continue
                seen_hashes[content_hash] = origin
                records.append({
                    "record_id": sha256_bytes(f"{source_id}:{origin}:{content_hash}".encode("utf-8")),
                    "source_id": source_id, "source_role": artifact.get("role", "general"),
                    "source_lineage": family[1], "document_family": family[1],
                    "conversation_family": family[2], "capability_family": family[3],
                    "origin": origin, "content_sha256": content_hash, "text": text,
                    "cleaning_reason_codes": ["CRLF_NORMALIZED"] if raw_text != text else [],
                })
                if max_records is not None and len(records) >= max_records:
                    break
            if max_records is not None and len(records) >= max_records:
                break
        if max_records is not None and len(records) >= max_records:
            break
    result = {
        "status": "PREPARED" if records else "BLOCKED_DATA",
        "acquisition_manifest_sha256": sha256_file(acquisition_manifest),
        "records": records, "record_count": len(records), "dropped": dropped,
        "dropped_count": len(dropped), "content_hash_algorithm": "sha256-utf8-clean-text-v1",
    }
    if not records:
        result["reason"] = "no usable records remained after deterministic cleaning"
    write_json(output, result)
    return result


def deterministic_split(records: Iterable[dict[str, Any]], ratios: dict[str, float], seed: int = 1729) -> list[dict[str, Any]]:
    values = [dict(record) for record in records]
    if not values:
        return []
    if any("record_id" not in record or not isinstance(record["record_id"], str) for record in values):
        raise ValueError("split records need immutable record_id")
    if not ratios or any(float(value) < 0 for value in ratios.values()) or abs(sum(float(value) for value in ratios.values()) - 1.0) > 1e-9:
        raise ValueError("split ratios must be nonnegative and sum to one")
    components: dict[int, list[dict[str, Any]]] = defaultdict(list)
    group_fields = ("source_lineage", "document_family", "conversation_family", "capability_family")
    # Build connected components over every declared family/lineage key. If
    # two records share any relation, they are assigned as one unit before a
    # split boundary is sampled. This prevents a later field from undoing an
    # earlier family grouping.
    parent = list(range(len(values)))
    def find(index: int) -> int:
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index
    def union(left: int, right: int) -> None:
        left_root, right_root = find(left), find(right)
        if left_root != right_root:
            parent[right_root] = left_root
    owners: dict[tuple[str, str], int] = {}
    for index, record in enumerate(values):
        for field in group_fields:
            value = record.get(field)
            if value:
                relation = (field, json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")))
                if relation in owners:
                    union(index, owners[relation])
                else:
                    owners[relation] = index
    for index, record in enumerate(values):
        components[find(index)].append(record)
    groups: dict[str, list[dict[str, Any]]] = {}
    for component in components.values():
        member_ids = sorted(record["record_id"] for record in component)
        family_key = sha256_bytes(canonical_json_bytes(["family-v1", member_ids]))
        groups[family_key] = component
    boundaries: list[tuple[str, float]] = []
    cursor = 0.0
    split_names = list(ratios)
    for split, fraction in ratios.items():
        cursor += float(fraction)
        boundaries.append((split, cursor))
    for key in sorted(groups):
        digest = sha256_bytes(canonical_json_bytes([seed, key]))
        point = int(digest[:16], 16) / float(16 ** 16)
        split = next(name for name, boundary in boundaries if point < boundary or name == split_names[-1])
        for record in groups[key]:
            record["family_key"] = key
            record["split"] = split
    return sorted(values, key=lambda item: item["record_id"])


def freeze(records_manifest: str | Path, output: str | Path, ratios: dict[str, float], seed: int = 1729) -> dict[str, Any]:
    payload = _load_json(records_manifest)
    records = payload.get("records", payload) if isinstance(payload, (dict, list)) else []
    excluded_roles = {"tokenizer_training_only", "training_only", "foundation_training_only"}
    excluded = [record for record in records if record.get("source_role") in excluded_roles]
    split_records = deterministic_split(
        [record for record in records if record.get("source_role") not in excluded_roles],
        ratios,
        seed,
    )
    result = {
        "status": "FROZEN" if split_records else "BLOCKED_DATA",
        "source_manifest_sha256": sha256_file(records_manifest),
        "records": split_records,
        "excluded_source_role_counts": {
            role: sum(record.get("source_role") == role for record in excluded)
            for role in sorted(excluded_roles)
            if any(record.get("source_role") == role for record in excluded)
        },
        "ratios": ratios,
        "seed": seed,
    }
    leakage = audit(split_records)
    result["leakage_audit"] = leakage
    if leakage["status"] != "PASS":
        raise EncoderError("BLOCKED_DATA_LEAKAGE", "frozen splits contain cross-split family leakage", leakage)
    write_json(output, result)
    return result


def audit(records: Iterable[dict[str, Any]]) -> dict[str, Any]:
    items = list(records)
    leaks: list[dict[str, Any]] = []
    for field in ("content_sha256", "source_lineage", "document_family", "conversation_family", "capability_family", "family_key"):
        owners: dict[str, str] = {}
        for record in items:
            value = record.get(field)
            split = record.get("split", "")
            if value is None:
                continue
            key = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            if key in owners and owners[key] != split:
                leaks.append({"field": field, "value": key, "first_split": owners[key], "split": split})
            else:
                owners[key] = split
    return {"status": "FAIL" if leaks else "PASS", "records": len(items), "leaks": leaks}

"""Public, machine-readable errors and deterministic precedence."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from .constants import ERROR_PRECEDENCE


@dataclass
class EncoderError(Exception):
    code: str
    message: str
    details: dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        super().__init__(self.message)

    def to_dict(self) -> dict[str, Any]:
        result: dict[str, Any] = {"error": self.code, "message": self.message}
        if self.details:
            result["details"] = self.details
        return result


def invalid_input(message: str, **details: Any) -> EncoderError:
    return EncoderError("INVALID_INPUT", message, details)


def input_too_long(message: str, **details: Any) -> EncoderError:
    return EncoderError("INPUT_TOO_LONG", message, details)


def invalid_registry(message: str, **details: Any) -> EncoderError:
    return EncoderError("INVALID_REGISTRY", message, details)


def index_mismatch(message: str, **details: Any) -> EncoderError:
    return EncoderError("INDEX_MISMATCH", message, details)


def numerical_error(message: str, **details: Any) -> EncoderError:
    return EncoderError("NUMERICAL_ERROR", message, details)


def precedence_document() -> list[str]:
    return list(ERROR_PRECEDENCE)

"""Dependency-free metric definitions for auditable small evaluation fixtures."""

from __future__ import annotations

import hashlib
import math
from collections import Counter
from typing import Iterable, Sequence


def macro_f1(predictions: Sequence[str], labels: Sequence[str], classes: Sequence[str] = ("CALL", "NO_CALL", "CLARIFY")) -> dict:
    if len(predictions) != len(labels):
        raise ValueError("predictions and labels must have equal length")
    per_class: dict[str, dict[str, float]] = {}
    for label in classes:
        tp = sum(prediction == label and truth == label for prediction, truth in zip(predictions, labels))
        fp = sum(prediction == label and truth != label for prediction, truth in zip(predictions, labels))
        fn = sum(prediction != label and truth == label for prediction, truth in zip(predictions, labels))
        precision = tp / (tp + fp) if tp + fp else 0.0
        recall = tp / (tp + fn) if tp + fn else 0.0
        f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
        per_class[label] = {"precision": precision, "recall": recall, "f1": f1, "support": tp + fn}
    return {"macro_f1": sum(item["f1"] for item in per_class.values()) / len(classes), "per_class": per_class, "support": len(labels)}


def false_call_rate(predictions: Sequence[str], labels: Sequence[str]) -> float:
    non_call = sum(label != "CALL" for label in labels)
    return sum(prediction == "CALL" and label != "CALL" for prediction, label in zip(predictions, labels)) / non_call if non_call else 0.0


def recall_at_k(rankings: Sequence[Sequence[str]], relevant: Sequence[set[str]], k: int = 8) -> float:
    values = []
    for ranking, gold in zip(rankings, relevant):
        if not gold:
            continue
        values.append(len(set(ranking[:k]) & gold) / len(gold))
    return sum(values) / len(values) if values else float("nan")


def ndcg(ranking: Sequence[str], relevance: dict[str, int], k: int = 10) -> float:
    actual = sum((2 ** relevance.get(item, 0) - 1) / math.log2(index + 2) for index, item in enumerate(ranking[:k]))
    ideal = sorted(relevance.values(), reverse=True)[:k]
    maximum = sum((2 ** value - 1) / math.log2(index + 2) for index, value in enumerate(ideal))
    return actual / maximum if maximum else float("nan")


def mrr(ranking: Sequence[str], relevant: set[str], k: int = 10) -> float:
    for index, item in enumerate(ranking[:k], 1):
        if item in relevant:
            return 1.0 / index
    return 0.0


def brier_score(probabilities: Sequence[Sequence[float]], labels: Sequence[int]) -> float:
    if len(probabilities) != len(labels) or not probabilities:
        raise ValueError("probabilities and labels must be matched and nonempty")
    total = 0.0
    for row, label in zip(probabilities, labels):
        values = [float(value) for value in row]
        if not 0 <= label < len(values) or not values or not all(math.isfinite(value) for value in values):
            raise ValueError("probabilities contain an invalid row or label")
        if any(value < 0.0 for value in values) or abs(sum(values) - 1.0) > 1e-6:
            raise ValueError("Brier score requires rows of nonnegative probabilities summing to one")
        total += sum((value - (1.0 if index == label else 0.0)) ** 2 for index, value in enumerate(values))
    return total / len(labels)


def expected_calibration_error(probabilities: Sequence[Sequence[float]], labels: Sequence[int], bins: int = 15) -> dict[str, object]:
    if bins <= 0:
        raise ValueError("bins must be positive")
    if len(probabilities) != len(labels) or not probabilities:
        raise ValueError("probabilities and labels must be matched and nonempty")
    counts = [0] * bins
    confidence = [0.0] * bins
    accuracy = [0.0] * bins
    for row, label in zip(probabilities, labels):
        values = [float(value) for value in row]
        if not values or not all(math.isfinite(value) for value in values) or not 0 <= label < len(values):
            raise ValueError("probabilities contain an invalid row or label")
        if any(value < 0.0 for value in values) or abs(sum(values) - 1.0) > 1e-6:
            raise ValueError("calibration error requires rows of nonnegative probabilities summing to one")
        prediction = max(range(len(values)), key=lambda index: (values[index], -index))
        confidence_value = values[prediction]
        bucket = min(bins - 1, int(max(0.0, min(1.0, confidence_value)) * bins))
        counts[bucket] += 1
        confidence[bucket] += confidence_value
        accuracy[bucket] += float(prediction == label)
    result_bins = []
    ece = 0.0
    for index, support in enumerate(counts):
        item = {"bin": index, "lower": index / bins, "upper": (index + 1) / bins, "support": support, "confidence": confidence[index] / support if support else 0.0, "accuracy": accuracy[index] / support if support else 0.0}
        result_bins.append(item)
        ece += abs(item["confidence"] - item["accuracy"]) * support / len(labels)
    return {"ece": ece, "bins": result_bins, "support": len(labels)}


def classification_report(predictions: Sequence[str], labels: Sequence[str], classes: Sequence[str] = ("CALL", "NO_CALL", "CLARIFY")) -> dict[str, object]:
    report = macro_f1(predictions, labels, classes)
    report["call_recall"] = report["per_class"].get("CALL", {}).get("recall", 0.0)
    report["false_call_rate"] = false_call_rate(predictions, labels)
    report["call_support"] = sum(label == "CALL" for label in labels)
    report["non_call_support"] = sum(label != "CALL" for label in labels)
    return report


def evaluate_predictions(rows: Sequence[dict[str, object]], *, ece_bins: int = 15, _include_slices: bool = True) -> dict[str, object]:
    """Compute the auditable metric bundle from materialized raw predictions.

    Each row may contain ``ranking``, ``relevant``, ``relevance``, ``prediction``,
    ``label``, ``logits``, and ``exact``. Missing optional component fields are
    reported as unavailable instead of silently changing denominators.
    """
    result: dict[str, object] = {"support": len(rows), "denominators": {"all_rows": len(rows)}}
    retrieval_rows = [row for row in rows if isinstance(row.get("ranking"), list) and isinstance(row.get("relevant"), (list, set, tuple))]
    if retrieval_rows:
        rankings = [row["ranking"] for row in retrieval_rows]
        relevant = [set(row["relevant"]) for row in retrieval_rows]
        result["shortlist_recall_at_8"] = recall_at_k(rankings, relevant, 8)
        result["retrieval_recall_at_10"] = recall_at_k(rankings, relevant, 10)
        result["any_hit_at_8"] = sum(bool(set(ranking[:8]) & gold) for ranking, gold in zip(rankings, relevant)) / len(retrieval_rows)
        result["denominators"]["retrieval"] = len(retrieval_rows)
        ndcg_values, mrr_values = [], []
        for row, gold in zip(retrieval_rows, relevant):
            relevance = row.get("relevance", {item: int(item in gold) for item in row["ranking"]})
            ndcg_values.append(ndcg(row["ranking"], relevance, 10))
            mrr_values.append(mrr(row["ranking"], gold, 10))
        result["retrieval_ndcg_at_10"] = sum(ndcg_values) / len(ndcg_values)
        result["retrieval_mrr_at_10"] = sum(mrr_values) / len(mrr_values)
        reranked_rows = [row for row in retrieval_rows if isinstance(row.get("reranked_ranking"), list)]
        if reranked_rows:
            rerank_ndcg = []
            rerank_mrr = []
            for row in reranked_rows:
                gold = set(row["relevant"])
                relevance = row.get("reranker_relevance", {item: int(item in gold) for item in row["reranked_ranking"]})
                rerank_ndcg.append(ndcg(row["reranked_ranking"], relevance, 10))
                rerank_mrr.append(mrr(row["reranked_ranking"], gold, 10))
            result["reranker_ndcg_at_10"] = sum(rerank_ndcg) / len(rerank_ndcg)
            result["reranker_mrr_at_10"] = sum(rerank_mrr) / len(rerank_mrr)
            result["denominators"]["reranker"] = len(reranked_rows)
    classification_rows = [row for row in rows if isinstance(row.get("prediction"), str) and isinstance(row.get("label"), str)]
    if classification_rows:
        predictions = [row["prediction"] for row in classification_rows]
        labels = [row["label"] for row in classification_rows]
        result.update({"decision_macro_f1": classification_report(predictions, labels)["macro_f1"], "per_class": classification_report(predictions, labels)["per_class"], "call_recall": classification_report(predictions, labels)["call_recall"], "false_call_rate": classification_report(predictions, labels)["false_call_rate"]})
        result["denominators"]["classification"] = len(classification_rows)
    probability_rows = [row for row in rows if isinstance(row.get("logits"), (list, tuple)) and isinstance(row.get("label_index"), int)]
    if probability_rows:
        probabilities = [row["logits"] for row in probability_rows]
        labels = [row["label_index"] for row in probability_rows]
        probability_values = _softmax_rows(probabilities)
        calibration = expected_calibration_error(probability_values, labels, bins=ece_bins)
        result.update({"nll": _nll(probabilities, labels), "brier": brier_score(probability_values, labels), "ece": calibration["ece"], "ece_bins": calibration["bins"]})
        result["denominators"]["calibration"] = len(probability_rows)
    exact_rows = [row for row in rows if isinstance(row.get("exact"), bool)]
    if exact_rows:
        result["end_to_end_exact_accuracy"] = sum(bool(row["exact"]) for row in exact_rows) / len(exact_rows)
        result["end_to_end_accuracy"] = result["end_to_end_exact_accuracy"]
        result["denominators"]["exact"] = len(exact_rows)
    path_rows = [row for row in rows if isinstance(row.get("rerank_invoked"), bool)]
    if path_rows:
        result["rerank_invocation_rate"] = sum(bool(row["rerank_invoked"]) for row in path_rows) / len(path_rows)
        result["denominators"]["path"] = len(path_rows)
    paired_rows = [row for row in rows if isinstance(row.get("conditional_exact"), bool) and isinstance(row.get("always_rerank_exact"), bool)]
    if paired_rows:
        conditional_accuracy = sum(bool(row["conditional_exact"]) for row in paired_rows) / len(paired_rows)
        always_accuracy = sum(bool(row["always_rerank_exact"]) for row in paired_rows) / len(paired_rows)
        conditional_false_calls = [row.get("conditional_false_call") for row in paired_rows if isinstance(row.get("conditional_false_call"), bool)]
        always_false_calls = [row.get("always_rerank_false_call") for row in paired_rows if isinstance(row.get("always_rerank_false_call"), bool)]
        result["fast_path_exact_accuracy"] = conditional_accuracy
        result["always_rerank_exact_accuracy"] = always_accuracy
        result["conditional_accuracy_difference"] = conditional_accuracy - always_accuracy
        if len(conditional_false_calls) == len(paired_rows) and len(always_false_calls) == len(paired_rows):
            result["conditional_false_call_difference"] = (sum(conditional_false_calls) - sum(always_false_calls)) / len(paired_rows)
        result["denominators"]["paired_paths"] = len(paired_rows)
    if _include_slices:
        slice_rows: dict[str, list[dict[str, object]]] = {}
        for row in rows:
            declared = row.get("slices", row.get("slice", []))
            if isinstance(declared, str):
                declared = [declared]
            if isinstance(declared, (list, tuple, set)):
                for name in declared:
                    if isinstance(name, str) and name:
                        slice_rows.setdefault(name, []).append(row)
        if slice_rows:
            result["slices"] = {name: evaluate_predictions(values, ece_bins=ece_bins, _include_slices=False) for name, values in sorted(slice_rows.items())}
    return result


def _softmax_rows(rows: Sequence[Sequence[float]]) -> list[list[float]]:
    output = []
    for row in rows:
        maximum = max(float(value) for value in row)
        values = [math.exp(float(value) - maximum) for value in row]
        total = sum(values)
        output.append([value / total for value in values])
    return output


def _nll(rows: Sequence[Sequence[float]], labels: Sequence[int]) -> float:
    total = 0.0
    for row, label in zip(rows, labels):
        values = [float(value) for value in row]
        maximum = max(values)
        total += math.log(sum(math.exp(value - maximum) for value in values)) + maximum - values[label]
    return total / len(labels)


def bootstrap_mean(values: Sequence[float], *, groups: Sequence[str] | None = None, samples: int = 1000, seed: int = 1729) -> dict[str, float | int]:
    if not values:
        raise ValueError("bootstrap requires nonempty values")
    if groups is None:
        groups = [str(index) for index in range(len(values))]
    if len(groups) != len(values):
        raise ValueError("bootstrap groups and values must match")
    grouped: dict[str, list[float]] = {}
    for group, value in zip(groups, values):
        grouped.setdefault(group, []).append(float(value))
    keys = sorted(grouped)
    if len(keys) < 2:
        mean = sum(values) / len(values)
        return {"mean": mean, "lower": mean, "upper": mean, "groups": len(keys), "samples": samples}
    import random

    rng = random.Random(seed)
    estimates = []
    for _ in range(samples):
        selected = [keys[rng.randrange(len(keys))] for _ in keys]
        sampled = [value for key in selected for value in grouped[key]]
        estimates.append(sum(sampled) / len(sampled))
    estimates.sort()
    lower_index = max(0, int(0.025 * len(estimates)) - 1)
    upper_index = min(len(estimates) - 1, int(0.975 * len(estimates)))
    return {"mean": sum(values) / len(values), "lower": estimates[lower_index], "upper": estimates[upper_index], "groups": len(keys), "samples": samples}

"""Materialize and verify a non-executable deployment export."""

from __future__ import annotations

import json
import shutil
from pathlib import Path
from typing import Any

from .artifacts import make_sha256sums, verify_sha256sums
from .constants import PARAMETER_COUNTS
from .errors import EncoderError
from .model import DeploymentModel, actual_parameter_counts, require_torch
from .utils import canonical_json_bytes, load_config, sha256_file, write_json


def _resolve_checkpoint(path: str | Path) -> tuple[Path, dict[str, Any]]:
    source = Path(path)
    if source.is_file():
        payload = json.loads(source.read_text(encoding="utf-8"))
        directory = payload.get("checkpoint_directory") or payload.get("directory")
        if directory is None:
            directory = source.parent / payload.get("checkpoint", "")
        source = Path(directory)
    metadata_path = source / "metadata.json"
    if not metadata_path.exists():
        raise EncoderError("BLOCKED_CHECKPOINT", "checkpoint metadata is absent", {"checkpoint": source.as_posix()})
    return source, json.loads(metadata_path.read_text(encoding="utf-8"))


def export_checkpoint(checkpoint: str | Path, output: str | Path, variant: str, *, tokenizer_directory: str | Path | None = None, model_config: str | Path | None = None, calibration: str | Path | None = None) -> dict[str, Any]:
    require_torch()
    try:
        from safetensors import torch as safe_torch
    except ImportError as exc:
        raise EncoderError("BLOCKED_ENVIRONMENT", "safe tensor serialization is required for deployment export", {"dependency": "safetensors"}) from exc
    checkpoint_dir, checkpoint_payload = _resolve_checkpoint(checkpoint)
    checkpoint_metadata = checkpoint_payload.get("metadata", checkpoint_payload)
    metadata_file = checkpoint_dir / "metadata.json"
    if metadata_file.exists():
        metadata_wrapper = json.loads(metadata_file.read_text(encoding="utf-8"))
        checkpoint_metadata = metadata_wrapper.get("metadata", metadata_wrapper)
    weights_path = checkpoint_dir / "model.safetensors"
    if not weights_path.exists():
        raise EncoderError("BLOCKED_CHECKPOINT", "checkpoint does not contain safe deployment weights", {"checkpoint": checkpoint_dir.as_posix()})
    state = safe_torch.load_file(str(weights_path), device="cpu")
    if not any(key.startswith("backbone.") for key in state):
        raise EncoderError("BLOCKED_CHECKPOINT", "selected checkpoint contains backbone-only or MLM weights; downstream heads are required")
    model = DeploymentModel(seed=1729)
    try:
        model.load_state_dict(state, strict=True)
    except RuntimeError as exc:
        raise EncoderError("BLOCKED_CHECKPOINT", "selected checkpoint state keys do not match the deployment model", {"reason": str(exc)}) from exc
    model.eval()
    counts = actual_parameter_counts(model)
    if counts["physical_named_parameters"] != PARAMETER_COUNTS["reranked_pipeline_deployed_total"]:
        raise EncoderError("BLOCKED_CHECKPOINT", "selected checkpoint parameter count is not the frozen deployment count", counts)
    if not tokenizer_directory or not (Path(tokenizer_directory) / "tokenizer.json").exists():
        raise EncoderError("BLOCKED_CHECKPOINT", "deployment export requires the promoted tokenizer directory")
    if calibration and not Path(calibration).exists():
        raise EncoderError("BLOCKED_CALIBRATION", "calibration manifest is absent")
    destination = Path(output)
    destination.mkdir(parents=True, exist_ok=True)
    deployment_state = {name: tensor.detach().cpu().contiguous() for name, tensor in model.state_dict().items()}
    safe_torch.save_file(deployment_state, str(destination / "model.safetensors"), metadata={"format": "juniper-deployment-v2", "variant": variant})
    config = model.backbone.config
    config_payload = load_config(model_config) if model_config else {"vocab_size": config.vocab_size, "blocks": config.blocks, "width": config.width, "q_heads": config.q_heads, "kv_heads": config.kv_heads, "head_dim": config.head_dim, "geglu_width": config.geglu_width, "rope_theta": config.rope_theta, "layer_norm_epsilon": config.layer_norm_epsilon, "dropout": config.dropout, "native_context": config.native_context}
    write_json(destination / "model_config.json", config_payload)
    if tokenizer_directory:
        tokenizer_source = Path(tokenizer_directory)
        shutil.copytree(tokenizer_source, destination / "tokenizer", dirs_exist_ok=True)
    else:
        raise EncoderError("BLOCKED_CHECKPOINT", "deployment export requires the promoted tokenizer directory")
    if calibration:
        calibration_source = Path(calibration)
        shutil.copy2(calibration_source, destination / "calibration.json")
    else:
        write_json(destination / "calibration.json", {"status": "NOT_CALIBRATED"})
    metadata = {
        "artifact_type": "juniper-deployment-export", "format_version": "juniper-export-v2", "variant": variant,
        "checkpoint_identity": checkpoint_payload.get("checkpoint_identity"), "checkpoint_directory": checkpoint_dir.as_posix(),
        "weights_sha256": sha256_file(destination / "model.safetensors"), "parameter_counts": counts,
        "tokenizer_identity": checkpoint_metadata.get("tokenizer_identity"),
        "status": "EXPORTED", "safe_weights": True,
    }
    write_json(destination / "export.json", metadata)
    make_sha256sums(destination, destination / "SHA256SUMS")
    return metadata


def verify_export(directory: str | Path) -> dict[str, Any]:
    require_torch()
    try:
        from safetensors import torch as safe_torch
    except ImportError as exc:
        raise EncoderError("BLOCKED_ENVIRONMENT", "safe tensor serialization is required for export verification", {"dependency": "safetensors"}) from exc
    root = Path(directory)
    export_path = root / "export.json"
    weights_path = root / "model.safetensors"
    if not export_path.exists() or not weights_path.exists():
        raise EncoderError("BLOCKED_EXPORT_PAYLOAD", "deployment export requires export.json and model.safetensors")
    payload = json.loads(export_path.read_text(encoding="utf-8"))
    if payload.get("status") != "EXPORTED" or payload.get("safe_weights") is not True:
        raise EncoderError("BLOCKED_EXPORT_PAYLOAD", "export is not a verified safe deployment payload")
    if payload.get("weights_sha256") != sha256_file(weights_path):
        raise EncoderError("BLOCKED_EXPORT_PAYLOAD", "deployment weights checksum mismatch")
    state = safe_torch.load_file(str(weights_path), device="cpu")
    model = DeploymentModel(seed=1729)
    model.load_state_dict(state, strict=True)
    counts = actual_parameter_counts(model)
    if counts["pad_row_max_abs"] != 0.0 or counts["physical_named_parameters"] != PARAMETER_COUNTS["reranked_pipeline_deployed_total"]:
        raise EncoderError("BLOCKED_EXPORT_PAYLOAD", "deployment payload failed parameter or PAD checks", counts)
    if not (root / "tokenizer/tokenizer.json").exists():
        raise EncoderError("BLOCKED_EXPORT_PAYLOAD", "deployment payload has no tokenizer")
    sums = root / "SHA256SUMS"
    if not sums.exists():
        raise EncoderError("BLOCKED_EXPORT_PAYLOAD", "deployment payload has no checksum manifest")
    verify_sha256sums(root, sums)
    return {"status": "PASS", "variant": payload.get("variant"), "parameter_counts": counts, "files": len(safe_torch.load_file(str(weights_path), device="cpu"))}


def load_float_export(directory: str | Path, *, device: str = "cpu") -> Any:
    """Load a verified floating export as an executable benchmark runner."""
    verify_export(directory)
    from safetensors.torch import load_file
    from .benchmark import make_model_runner

    model = DeploymentModel(seed=1729)
    model.load_state_dict(load_file(str(Path(directory) / "model.safetensors"), device="cpu"), strict=True)
    return make_model_runner(model, device=device)

"""Strict registry/request validation and deterministic routing templates."""

from __future__ import annotations

import dataclasses
import json
import re
from collections.abc import Mapping, Sequence
from typing import Any

from .constants import (
    CLASS_NAMES,
    MAX_ORDINARY_DECISION_CONTENT_TOKENS,
    MAX_ORDINARY_PAIR_CONTENT_TOKENS,
    MAX_ORDINARY_REQUEST_TOKENS,
    STRUCTURAL_IDS,
    UNICODE_DATABASE_VERSION,
)
from .errors import EncoderError, input_too_long, invalid_input, invalid_registry
from .tokenizer import RawByteBPE
from .utils import canonical_json_bytes, sha256_bytes, strict_json_loads


REGISTRY_FIELDS = (
    "id",
    "type",
    "name",
    "purpose",
    "supported_requests",
    "exclusions",
    "required_inputs",
)
ALLOWED_TYPES = frozenset(("agent", "tool", "skill"))
CAPABILITY_ID_RE = re.compile(r"^[A-Za-z0-9._-]+$")


@dataclasses.dataclass(frozen=True)
class RegistryRecord:
    id: str
    type: str
    name: str
    purpose: str
    supported_requests: tuple[str, ...]
    exclusions: tuple[str, ...]
    required_inputs: tuple[str, ...]

    @classmethod
    def from_mapping(cls, value: Mapping[str, Any]) -> "RegistryRecord":
        if not isinstance(value, Mapping):
            raise invalid_registry("capability record must be an object")
        if tuple(value.keys()) != REGISTRY_FIELDS:
            raise invalid_registry("capability record must contain exactly the seven fields in frozen order", fields=list(value.keys()))
        for field in REGISTRY_FIELDS[:4]:
            if not isinstance(value[field], str) or not value[field]:
                raise invalid_registry(f"record field {field} must be a nonempty string")
        capability_id = value["id"]
        if not capability_id.isascii() or not CAPABILITY_ID_RE.fullmatch(capability_id):
            raise invalid_registry("capability id must be nonempty ASCII matching [A-Za-z0-9._-]+", id=capability_id)
        if value["type"] not in ALLOWED_TYPES:
            raise invalid_registry("record type is not allowed", type=value["type"])
        arrays: dict[str, tuple[str, ...]] = {}
        for field in REGISTRY_FIELDS[4:]:
            raw = value[field]
            if not isinstance(raw, list) or any(not isinstance(item, str) or not item for item in raw):
                raise invalid_registry(f"record field {field} must be an array of nonempty strings")
            arrays[field] = tuple(raw)
        return cls(
            id=capability_id,
            type=value["type"],
            name=value["name"],
            purpose=value["purpose"],
            **arrays,
        )

    def as_mapping(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "type": self.type,
            "name": self.name,
            "purpose": self.purpose,
            "supported_requests": list(self.supported_requests),
            "exclusions": list(self.exclusions),
            "required_inputs": list(self.required_inputs),
        }

    def serialized(self) -> bytes:
        return canonical_json_bytes(self.as_mapping())

    def description_hash(self) -> str:
        return sha256_bytes(self.serialized())


def parse_registry_json(raw: str | bytes) -> list[RegistryRecord]:
    try:
        value = strict_json_loads(raw)
    except (ValueError, json.JSONDecodeError) as exc:
        raise invalid_registry("registry is not strict JSON", reason=str(exc)) from exc
    if not isinstance(value, list):
        raise invalid_registry("registry must be an array")
    records = [RegistryRecord.from_mapping(item) for item in value]
    ids = [record.id for record in records]
    if len(ids) != len(set(ids)):
        raise invalid_registry("capability IDs must be unique and case-sensitive")
    return records


@dataclasses.dataclass(frozen=True)
class HistoryEntry:
    role: str
    content: str

    def as_mapping(self) -> dict[str, str]:
        return {"role": self.role, "content": self.content}


@dataclasses.dataclass(frozen=True)
class FormattedRequest:
    history: tuple[HistoryEntry, ...]
    user: str
    serialized: bytes
    dropped_history_count: int
    token_ids: tuple[int, ...]


def _validate_request_shape(request: Mapping[str, Any]) -> tuple[list[HistoryEntry], str]:
    if not isinstance(request, Mapping) or tuple(request.keys()) != ("history", "user"):
        raise invalid_input("request must contain exactly history and user in frozen order")
    history = request["history"]
    user = request["user"]
    if not isinstance(history, list):
        raise invalid_input("history must be an array")
    if not isinstance(user, str) or not user or user.isspace():
        raise invalid_input("user must not be empty or Unicode-whitespace-only", unicode_database=UNICODE_DATABASE_VERSION)
    entries: list[HistoryEntry] = []
    for item in history:
        if not isinstance(item, Mapping) or tuple(item.keys()) != ("role", "content"):
            raise invalid_input("each history entry must contain role and content in frozen order")
        if item["role"] not in {"user", "assistant", "tool"}:
            raise invalid_input("history role must be one of user, assistant, or tool")
        if not isinstance(item["content"], str):
            raise invalid_input("history content must be a string")
        entries.append(HistoryEntry(item["role"], item["content"]))
    return entries, user


def serialize_request(history: Sequence[HistoryEntry], user: str) -> bytes:
    return canonical_json_bytes({
        "history": [entry.as_mapping() for entry in history],
        "user": user,
    })


def format_request(request: Mapping[str, Any], tokenizer: RawByteBPE) -> FormattedRequest:
    history, user = _validate_request_shape(request)
    current = serialize_request([], user)
    user_token_count = len(tokenizer.encode(current.decode("utf-8")))
    if user_token_count > MAX_ORDINARY_REQUEST_TOKENS:
        raise input_too_long("serialized user-alone request exceeds the ordinary-token budget", token_count=user_token_count)
    retained = list(history)
    dropped = 0
    serialized = serialize_request(retained, user)
    while len(tokenizer.encode(serialized.decode("utf-8"))) > MAX_ORDINARY_REQUEST_TOKENS:
        if not retained:
            raise input_too_long("serialized request exceeds the ordinary-token budget")
        retained.pop(0)
        dropped += 1
        serialized = serialize_request(retained, user)
    token_ids = tuple(tokenizer.encode(serialized.decode("utf-8")))
    return FormattedRequest(tuple(retained), user, serialized, dropped, token_ids)


def _structural(name: str) -> int:
    return STRUCTURAL_IDS[name]


@dataclasses.dataclass(frozen=True)
class PairInput:
    token_ids: tuple[int, ...]
    query_tokens: tuple[int, ...]
    document_tokens: tuple[int, ...]
    content_tokens: int


def format_generic_pair(
    query_serialized: bytes,
    record: RegistryRecord,
    tokenizer: RawByteBPE,
    *,
    allow_document_truncation: bool = True,
) -> PairInput:
    try:
        query_text = query_serialized.decode("utf-8", "strict")
    except UnicodeDecodeError as exc:
        raise invalid_input("request bytes are not valid UTF-8", reason=str(exc)) from exc
    query_tokens = tokenizer.encode(query_text)
    if len(query_tokens) > MAX_ORDINARY_REQUEST_TOKENS:
        raise input_too_long("serialized query exceeds the query-token budget", token_count=len(query_tokens))
    document_tokens = tokenizer.encode(record.serialized().decode("utf-8"))
    remaining = MAX_ORDINARY_PAIR_CONTENT_TOKENS - len(query_tokens)
    if remaining < 0:
        raise input_too_long("query leaves no capacity for a generic pair")
    if len(document_tokens) > remaining and not allow_document_truncation:
        raise input_too_long("registered capability record cannot be truncated in routing", capability_id=record.id)
    document_tokens = document_tokens[:remaining]
    token_ids = (
        _structural("[CLS]"), _structural("[QUERY]"), *query_tokens,
        _structural("[SEP]"), _structural("[DOCUMENT]"), *document_tokens,
        _structural("[SEP]"),
    )
    return PairInput(tuple(token_ids), tuple(query_tokens), tuple(document_tokens), len(query_tokens) + len(document_tokens))


@dataclasses.dataclass(frozen=True)
class DecisionInput:
    token_ids: tuple[int, ...]
    candidate_ids: tuple[str, ...]
    content_tokens: int


def format_decision(
    query_serialized: bytes,
    candidates: Sequence[RegistryRecord],
    tokenizer: RawByteBPE,
) -> DecisionInput:
    if not 1 <= len(candidates) <= 2:
        raise invalid_input("decision classifier accepts one or two candidates")
    try:
        request_value = json.loads(query_serialized.decode("utf-8", "strict"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise invalid_input("request bytes are not valid UTF-8 JSON", reason=str(exc)) from exc
    if not isinstance(request_value, dict) or tuple(request_value.keys()) != ("history", "user"):
        raise invalid_input("decision request must be the validated compact request object")

    def serialize(records: Sequence[RegistryRecord]) -> bytes:
        return canonical_json_bytes({"request": request_value, "capabilities": [record.as_mapping() for record in records]})

    selected = list(candidates)
    serialized = serialize(selected)
    content_tokens = tokenizer.encode(serialized.decode("utf-8"))
    if len(content_tokens) > MAX_ORDINARY_DECISION_CONTENT_TOKENS and len(selected) == 2:
        selected = selected[:1]
        serialized = serialize(selected)
        content_tokens = tokenizer.encode(serialized.decode("utf-8"))
    if len(content_tokens) > MAX_ORDINARY_DECISION_CONTENT_TOKENS:
        raise input_too_long("decision context exceeds the ordinary-token budget", content_tokens=len(content_tokens))
    token_ids = (_structural("[CLS]"), _structural("[QUERY]"), *content_tokens, _structural("[SEP]"))
    return DecisionInput(tuple(token_ids), tuple(record.id for record in selected), len(content_tokens))


def validate_decision(decision: Mapping[str, Any], allowed_ids: set[str]) -> None:
    if tuple(decision.keys()) != ("decision", "capability_id"):
        raise invalid_input("decision must contain decision and capability_id in frozen order")
    if decision["decision"] not in CLASS_NAMES:
        raise invalid_input("unknown decision class")
    capability_id = decision["capability_id"]
    if decision["decision"] == "CALL":
        if not isinstance(capability_id, str) or capability_id not in allowed_ids:
            raise invalid_input("CALL capability_id is not present in the current registry")
    elif capability_id is not None:
        raise invalid_input("non-CALL decisions must have a null capability_id")

"""Matched INT8 gate calculations. A missing measurement is never a pass."""

from __future__ import annotations

import copy
import json
import shutil
from pathlib import Path
from typing import Any

from .artifacts import make_sha256sums, verify_sha256sums
from .errors import EncoderError
from .utils import load_config, sha256_file, write_json


def compare_metrics(floating: dict[str, float], int8: dict[str, float], gates: dict[str, float]) -> dict[str, Any]:
    metric_losses = {}
    failures = []
    for metric, tolerance in (
        ("shortlist_recall_at_8", 0.01), ("retrieval_recall_at_10", 0.01), ("retrieval_ndcg_at_10", 0.01),
        ("reranker_ndcg_at_10", 0.01), ("reranker_mrr_at_10", 0.01), ("decision_macro_f1", 0.01),
        ("call_recall", 0.01), ("end_to_end_accuracy", 0.01),
    ):
        if metric not in floating or metric not in int8:
            failures.append({"metric": metric, "reason": "missing matched measurement"})
            continue
        loss = floating[metric] - int8[metric]
        metric_losses[metric] = loss
        if loss > tolerance:
            failures.append({"metric": metric, "loss": loss, "tolerance": tolerance})
    if "false_call_rate" in floating and "false_call_rate" in int8:
        increase = int8["false_call_rate"] - floating["false_call_rate"]
        metric_losses["false_call_rate_increase"] = increase
        if increase > 0.005:
            failures.append({"metric": "false_call_rate", "increase": increase, "tolerance": 0.005})
    else:
        failures.append({"metric": "false_call_rate", "reason": "missing matched measurement"})
    if "ece" in floating and "ece" in int8:
        increase = int8["ece"] - floating["ece"]
        metric_losses["ece_increase"] = increase
        if increase > 0.01:
            failures.append({"metric": "ece", "increase": increase, "tolerance": 0.01})
    else:
        failures.append({"metric": "ece", "reason": "missing matched measurement"})
    limits = {"warm_p50_latency_ratio": gates.get("p50_ratio", 1.05), "warm_p95_latency_ratio": gates.get("p95_ratio", 1.05), "artifact_size_ratio": gates.get("artifact_size_ratio", 0.65), "peak_memory_ratio": gates.get("peak_memory_ratio", 1.0)}
    for metric, ratio_limit in limits.items():
        if metric not in int8:
            failures.append({"metric": metric, "reason": "missing matched measurement"})
        elif (metric in {"artifact_size_ratio", "peak_memory_ratio"} and int8[metric] > ratio_limit) or (metric.startswith("warm_") and int8[metric] > ratio_limit):
            failures.append({"metric": metric, "ratio": int8[metric], "limit": ratio_limit})
    if int8.get("numerical_failures", 1) != 0:
        failures.append({"metric": "numerical_validity", "reason": "one or more numerical failures"})
    return {"status": "INT8_ACCEPTED" if not failures else "INT8_REJECTED", "losses": metric_losses, "failures": failures}


def _require_torch() -> Any:
    try:
        import torch
        from torch import nn
    except ImportError as exc:
        raise EncoderError("BLOCKED_ENVIRONMENT", "INT8 construction requires PyTorch") from exc
    return torch, nn


def _quantize_weight(weight: Any) -> tuple[Any, Any]:
    torch, _ = _require_torch()
    scales = weight.detach().float().abs().amax(dim=1).clamp_min(1e-12) / 127.0
    quantized = torch.round(weight.detach().float() / scales.unsqueeze(1)).clamp(-127, 127).to(torch.int8)
    return quantized.cpu().contiguous(), scales.cpu().contiguous()


class Int8Linear:
    """Portable post-training INT8 linear with explicit per-output scales.

    The module stores weights as int8 and dequantizes immediately before the
    matmul. This is a genuine INT8 payload and a deterministic fallback for
    runtimes without a validated fused backend; its qualification report makes
    the lack of fused INT8 execution visible.
    """

    def __new__(cls, linear: Any) -> Any:
        torch, nn = _require_torch()

        class _Impl(nn.Module):
            def __init__(self) -> None:
                super().__init__()
                quantized, scales = _quantize_weight(linear.weight)
                self.register_buffer("weight_int8", quantized)
                self.register_buffer("weight_scale", scales)
                if linear.bias is not None:
                    self.register_buffer("bias", linear.bias.detach().cpu().contiguous())
                else:
                    self.bias = None

            def forward(self, inputs: Any) -> Any:
                import torch.nn.functional as F

                weight = self.weight_int8.float() * self.weight_scale.float().unsqueeze(1)
                return F.linear(inputs.float(), weight, self.bias.float() if self.bias is not None else None).to(dtype=inputs.dtype)

        return _Impl()


def quantize_model(model: Any) -> tuple[Any, list[dict[str, Any]]]:
    torch, nn = _require_torch()
    quantized = copy.deepcopy(model).cpu().eval()
    operators: list[dict[str, Any]] = []
    for block_index, block in enumerate(quantized.backbone.blocks):
        for name in ("query", "key", "value", "output", "ffn_in", "down"):
            module = getattr(block, name)
            if not isinstance(module, nn.Linear):
                raise EncoderError("BLOCKED_INT8", "eligible backbone operator is not a linear module", {"module": f"backbone.blocks.{block_index}.{name}"})
            setattr(block, name, Int8Linear(module))
            module_name = f"backbone.blocks.{block_index}.{name}"
            operators.append({"module": module_name, "weight_dtype": "int8", "activation_dtype": "float32", "axis": 0, "scale_storage": f"{module_name}.weight_scale", "backend": "portable-dequantized-linear"})
    return quantized, operators


def quantize_export(floating_directory: str | Path, output: str | Path, config_path: str | Path | None = None) -> dict[str, Any]:
    torch, _ = _require_torch()
    try:
        from safetensors import torch as safe_torch
        from .model import DeploymentModel
    except ImportError as exc:
        raise EncoderError("BLOCKED_ENVIRONMENT", "INT8 export requires safetensors and PyTorch") from exc
    source = Path(floating_directory)
    weights = source / "model.safetensors"
    if not weights.exists() or not (source / "export.json").exists():
        raise EncoderError("BLOCKED_INT8", "floating deployment export is absent")
    from .export import verify_export

    verify_export(source)
    model = DeploymentModel(seed=1729)
    model.load_state_dict(safe_torch.load_file(str(weights), device="cpu"), strict=True)
    quantized, operators = quantize_model(model)
    destination = Path(output)
    destination.mkdir(parents=True, exist_ok=True)
    tensors = {name: tensor.detach().cpu().contiguous() for name, tensor in quantized.state_dict().items()}
    safe_torch.save_file(tensors, str(destination / "model.safetensors"), metadata={"format": "juniper-int8-v1"})
    for name in ("model_config.json", "calibration.json"):
        if (source / name).exists():
            shutil.copy2(source / name, destination / name)
    if (source / "tokenizer").exists():
        shutil.copytree(source / "tokenizer", destination / "tokenizer", dirs_exist_ok=True)
    payload = {"artifact_type": "juniper-deployment-export", "format_version": "juniper-int8-v1", "variant": "int8", "status": "EXPORTED", "source_export_sha256": sha256_file(source / "model.safetensors"), "weights_sha256": sha256_file(destination / "model.safetensors"), "operators": operators, "excluded_modules": ["embedding", "LayerNorm", "softmax", "mean_pooling", "l2_normalization", "retrieval", "classifier", "reranker"], "backend": "portable-dequantized-linear", "calibration_subset": load_config(config_path).get("calibration_subset") if config_path else "quantization-calibration"}
    write_json(destination / "export.json", payload)
    make_sha256sums(destination, destination / "SHA256SUMS")
    return payload


def _load_quantized_model(directory: str | Path) -> Any:
    from safetensors.torch import load_file
    from .model import DeploymentModel

    model = DeploymentModel(seed=1729)
    model, _ = quantize_model(model)
    model.load_state_dict(load_file(str(Path(directory) / "model.safetensors"), device="cpu"), strict=True)
    return model


def verify_int8_export(directory: str | Path) -> dict[str, Any]:
    """Verify the portable INT8 payload and run one finite inference probe."""
    torch, _ = _require_torch()
    root = Path(directory)
    export_path = root / "export.json"
    weights_path = root / "model.safetensors"
    if not export_path.exists() or not weights_path.exists():
        raise EncoderError("BLOCKED_INT8", "INT8 export requires export.json and model.safetensors")
    payload = json.loads(export_path.read_text(encoding="utf-8"))
    if payload.get("status") != "EXPORTED" or payload.get("format_version") != "juniper-int8-v1" or payload.get("variant") != "int8":
        raise EncoderError("BLOCKED_INT8", "payload is not a Juniper INT8 export")
    if payload.get("weights_sha256") != sha256_file(weights_path):
        raise EncoderError("BLOCKED_INT8", "INT8 weights checksum mismatch")
    sums_path = root / "SHA256SUMS"
    if not sums_path.exists():
        raise EncoderError("BLOCKED_INT8", "INT8 export checksum manifest is absent")
    verify_sha256sums(root, sums_path)
    from safetensors.torch import load_file

    tensors = load_file(str(weights_path), device="cpu")
    operators = payload.get("operators", [])
    missing = [item["scale_storage"] for item in operators if item.get("scale_storage") not in tensors or tensors[item["scale_storage"]].dtype != torch.float32]
    int8_keys = [item["module"] + ".weight_int8" for item in operators]
    missing.extend(key for key in int8_keys if key not in tensors or tensors[key].dtype != torch.int8)
    if missing:
        raise EncoderError("BLOCKED_INT8", "INT8 payload is missing declared quantization tensors", {"missing": missing[:20]})
    model = _load_quantized_model(root).eval()
    with torch.inference_mode():
        outputs = (model.retrieval_vector(torch.full((1, 8), 7, dtype=torch.long)), model.classify(torch.full((1, 8), 7, dtype=torch.long)), model.rerank(torch.full((1, 8), 7, dtype=torch.long)))
    if not all(bool(torch.isfinite(output).all()) for output in outputs):
        raise EncoderError("BLOCKED_INT8", "INT8 finite-output probe failed")
    return {"status": "PASS", "variant": "int8", "operators": len(operators), "int8_tensors": len(int8_keys), "backend": payload.get("backend"), "finite_probe": True}


def load_int8_export(directory: str | Path, *, device: str = "cpu") -> Any:
    """Load a verified INT8 export as an executable benchmark runner."""
    verify_int8_export(directory)
    from .benchmark import make_model_runner

    return make_model_runner(_load_quantized_model(directory), device=device)

"""Immutable registry snapshots and exact FP32 normalized-dot-product indexes."""

from __future__ import annotations

import dataclasses
import json
import math
from array import array
from pathlib import Path
from typing import Callable, Iterable, Sequence

from .errors import index_mismatch, invalid_registry, numerical_error
from .formatting import RegistryRecord, parse_registry_json
from .utils import canonical_json_bytes, require_finite, sha256_bytes, write_json


@dataclasses.dataclass(frozen=True)
class RegistrySnapshot:
    records: tuple[RegistryRecord, ...]
    tokenizer_identity: str
    encoder_variant_identity: str
    snapshot_identity: str

    @classmethod
    def create(
        cls,
        records: Iterable[RegistryRecord],
        *,
        tokenizer_identity: str,
        encoder_variant_identity: str,
    ) -> "RegistrySnapshot":
        ordered = tuple(records)
        ids = [record.id for record in ordered]
        if len(ids) != len(set(ids)):
            raise invalid_registry("registry IDs must be unique")
        identity_payload = {
            "records": [record.as_mapping() for record in ordered],
            "tokenizer_identity": tokenizer_identity,
            "encoder_variant_identity": encoder_variant_identity,
        }
        identity = sha256_bytes(canonical_json_bytes(identity_payload))
        return cls(ordered, tokenizer_identity, encoder_variant_identity, identity)

    @classmethod
    def from_json(cls, path: str | Path, *, tokenizer_identity: str, encoder_variant_identity: str) -> "RegistrySnapshot":
        records = parse_registry_json(Path(path).read_bytes())
        return cls.create(records, tokenizer_identity=tokenizer_identity, encoder_variant_identity=encoder_variant_identity)

    def as_payload(self) -> dict:
        return {
            "records": [record.as_mapping() for record in self.records],
            "tokenizer_identity": self.tokenizer_identity,
            "encoder_variant_identity": self.encoder_variant_identity,
            "snapshot_identity": self.snapshot_identity,
        }

    def save(self, path: str | Path) -> None:
        write_json(path, self.as_payload())

    @classmethod
    def load(cls, path: str | Path) -> "RegistrySnapshot":
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
        records = tuple(RegistryRecord.from_mapping(item) for item in payload.get("records", []))
        snapshot = cls.create(records, tokenizer_identity=payload["tokenizer_identity"], encoder_variant_identity=payload["encoder_variant_identity"])
        if snapshot.snapshot_identity != payload.get("snapshot_identity"):
            raise invalid_registry("registry snapshot identity mismatch")
        return snapshot

@dataclasses.dataclass(frozen=True)
class RegistryIndex:
    snapshot_identity: str
    tokenizer_identity: str
    encoder_variant_identity: str
    dimension: int
    vectors: tuple[tuple[float, ...], ...]
    index_identity: str

    @classmethod
    def build(
        cls,
        snapshot: RegistrySnapshot,
        encoder: Callable[[RegistryRecord], Sequence[float]],
        *,
        dimension: int = 256,
    ) -> "RegistryIndex":
        vectors: list[tuple[float, ...]] = []
        for record in snapshot.records:
            raw = tuple(float(value) for value in encoder(record))
            if len(raw) != dimension:
                raise index_mismatch("registry vector dimension mismatch", capability_id=record.id, expected=dimension, actual=len(raw))
            require_finite(raw, f"registry vector {record.id}")
            norm = math.sqrt(math.fsum(value * value for value in raw))
            if norm < 1e-12:
                raise numerical_error("registry vector norm is below threshold", capability_id=record.id)
            vectors.append(tuple(value / norm for value in raw))
        payload = {
            "snapshot_identity": snapshot.snapshot_identity,
            "tokenizer_identity": snapshot.tokenizer_identity,
            "encoder_variant_identity": snapshot.encoder_variant_identity,
            "dimension": dimension,
            "vectors": [list(vector) for vector in vectors],
        }
        return cls(
            snapshot.snapshot_identity,
            snapshot.tokenizer_identity,
            snapshot.encoder_variant_identity,
            dimension,
            tuple(vectors),
            sha256_bytes(canonical_json_bytes(payload)),
        )

    def verify_compatible(self, snapshot: RegistrySnapshot, *, tokenizer_identity: str, encoder_variant_identity: str) -> None:
        if (
            self.snapshot_identity != snapshot.snapshot_identity
            or self.tokenizer_identity != tokenizer_identity
            or self.encoder_variant_identity != encoder_variant_identity
            or len(self.vectors) != len(snapshot.records)
        ):
            raise index_mismatch(
                "index does not match the active registry/tokenizer/encoder variant",
                index_snapshot=self.snapshot_identity,
                active_snapshot=snapshot.snapshot_identity,
            )
        for vector in self.vectors:
            if len(vector) != self.dimension:
                raise index_mismatch("index contains a vector with the wrong dimension")
            require_finite(vector, "index vector")

    def search(self, query: Sequence[float], snapshot: RegistrySnapshot, *, limit: int = 8) -> list[tuple[RegistryRecord, float]]:
        self.verify_compatible(snapshot, tokenizer_identity=self.tokenizer_identity, encoder_variant_identity=self.encoder_variant_identity)
        query_values = tuple(float(value) for value in query)
        if len(query_values) != self.dimension:
            raise index_mismatch("query vector dimension mismatch", expected=self.dimension, actual=len(query_values))
        require_finite(query_values, "query vector")
        norm = math.sqrt(math.fsum(value * value for value in query_values))
        if norm < 1e-12:
            raise numerical_error("query vector norm is below threshold")
        normalized = tuple(value / norm for value in query_values)
        scored = [
            (snapshot.records[i], math.fsum(normalized[j] * self.vectors[i][j] for j in range(self.dimension)))
            for i in range(len(snapshot.records))
        ]
        require_finite((score for _, score in scored), "search score")
        scored.sort(key=lambda item: (-item[1], item[0].id.encode("ascii")))
        return scored[: min(limit, len(scored))]

    def as_payload(self) -> dict:
        return {
            "snapshot_identity": self.snapshot_identity,
            "tokenizer_identity": self.tokenizer_identity,
            "encoder_variant_identity": self.encoder_variant_identity,
            "dimension": self.dimension,
            "vectors": [list(vector) for vector in self.vectors],
            "index_identity": self.index_identity,
        }

    def save(self, path: str | Path) -> None:
        write_json(path, self.as_payload())

    @classmethod
    def load(cls, path: str | Path) -> "RegistryIndex":
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
        vectors = tuple(tuple(float(value) for value in vector) for vector in payload.get("vectors", []))
        index = cls(payload["snapshot_identity"], payload["tokenizer_identity"], payload["encoder_variant_identity"], int(payload["dimension"]), vectors, payload["index_identity"])
        expected = dict(payload)
        expected.pop("index_identity", None)
        if sha256_bytes(canonical_json_bytes(expected)) != index.index_identity:
            raise index_mismatch("registry index identity mismatch")
        return index


def embedding_cache_key(record: RegistryRecord, *, tokenizer_identity: str, encoder_variant_identity: str) -> str:
    """Stable key used by optional external caches; description changes invalidate it."""
    return sha256_bytes(canonical_json_bytes({"capability_id": record.id, "description_hash": record.description_hash(), "tokenizer_identity": tokenizer_identity, "encoder_variant_identity": encoder_variant_identity}))

"""Raw UTF-8 byte BPE with a deterministic, lossless artifact format."""

from __future__ import annotations

import base64
import collections
import dataclasses
import re
from pathlib import Path
from typing import Iterable, Sequence

from .constants import (
    BYTE_OFFSET,
    FIRST_MERGE_ID,
    LAST_TOKEN_ID,
    MERGE_COUNT,
    STRUCTURAL_IDS,
    VOCAB_SIZE,
)
from .errors import EncoderError, input_too_long, invalid_input
from .utils import canonical_json_bytes, sha256_bytes, sha256_file, write_json


STRUCTURAL_TEXT = frozenset(STRUCTURAL_IDS)
_SURROGATE_RE = re.compile(r"[\ud800-\udfff]")


def _strict_utf8(text: str) -> bytes:
    if not isinstance(text, str):
        raise invalid_input("content must be a Unicode string")
    if _SURROGATE_RE.search(text):
        raise invalid_input("lone UTF-16 surrogate is not a Unicode scalar sequence")
    try:
        return text.encode("utf-8", "strict")
    except UnicodeEncodeError as exc:
        raise invalid_input("content is not valid UTF-8", reason=str(exc)) from exc


def _token_bytes(token_id: int) -> bytes:
    if not BYTE_OFFSET <= token_id <= BYTE_OFFSET + 255:
        raise ValueError(f"not a byte token: {token_id}")
    return bytes((token_id - BYTE_OFFSET,))


@dataclasses.dataclass(frozen=True)
class TokenizerConfig:
    merge_count: int = MERGE_COUNT
    vocab_size: int = VOCAB_SIZE
    implementation_version: str = "raw-byte-bpe-v1"
    unicode_database: str = "python-unicode-database"
    tie_break: str = "numeric-left-right"
    overlap_rule: str = "left-to-right-non-overlapping"

    def validate(self) -> None:
        if self.vocab_size != VOCAB_SIZE or self.merge_count != MERGE_COUNT:
            raise ValueError("deployment tokenizer must use the frozen 16,384 vocabulary and 16,121 merges")


@dataclasses.dataclass(frozen=True)
class Merge:
    left: int
    right: int
    new_id: int

    def as_list(self) -> list[int]:
        return [self.left, self.right, self.new_id]


class RawByteBPE:
    """A tokenizer that never normalizes, pretokenizes, or replaces bytes."""

    def __init__(self, merges: Sequence[Merge], *, config: TokenizerConfig | None = None) -> None:
        self.config = config or TokenizerConfig(merge_count=len(merges), vocab_size=FIRST_MERGE_ID + len(merges))
        if self.config.merge_count != len(merges):
            raise ValueError("config merge_count does not match merges")
        self.merges = tuple(merges)
        self._pair_to_id: dict[tuple[int, int], int] = {}
        self._bytes_by_id: dict[int, bytes] = {i: _token_bytes(i) for i in range(BYTE_OFFSET, BYTE_OFFSET + 256)}
        for merge in self.merges:
            if merge.new_id in self._bytes_by_id:
                raise ValueError(f"duplicate token id {merge.new_id}")
            if merge.new_id != FIRST_MERGE_ID + len(self._pair_to_id):
                raise ValueError("merge IDs must be contiguous in learned order")
            if (merge.left, merge.right) in self._pair_to_id:
                raise ValueError("duplicate merge pair")
            if merge.left not in self._bytes_by_id or merge.right not in self._bytes_by_id:
                raise ValueError("merge history references a token not learned yet")
            merged = self._bytes_by_id[merge.left] + self._bytes_by_id[merge.right]
            if merged in self._bytes_by_id.values():
                raise ValueError("learned token has a duplicate byte representation")
            self._pair_to_id[(merge.left, merge.right)] = merge.new_id
            self._bytes_by_id[merge.new_id] = merged
        if len(self._bytes_by_id) != 256 + len(self.merges):
            raise ValueError("token byte map is not unique")

    @classmethod
    def from_merges(cls, pairs: Sequence[tuple[int, int]], *, toy: bool = False) -> "RawByteBPE":
        merges = [Merge(left, right, FIRST_MERGE_ID + i) for i, (left, right) in enumerate(pairs)]
        if toy:
            config = TokenizerConfig(merge_count=len(merges), vocab_size=FIRST_MERGE_ID + len(merges))
        else:
            config = TokenizerConfig()
        return cls(merges, config=config)

    @classmethod
    def train(
        cls,
        documents: Iterable[str],
        *,
        config: TokenizerConfig | None = None,
        require_full: bool = True,
    ) -> "RawByteBPE":
        config = config or TokenizerConfig()
        documents_bytes = [_strict_utf8(document) for document in documents]
        byte_map = {i: _token_bytes(i) for i in range(BYTE_OFFSET, BYTE_OFFSET + 256)}
        byte_representations = set(byte_map.values())
        merges: list[Merge] = []
        next_id = FIRST_MERGE_ID

        # Maintain each document as a linked list of token nodes. Pair counts
        # and occurrence sets are updated only around a replacement, while a
        # heap supplies the same ``max frequency, numeric pair`` ordering as
        # the straightforward reference implementation. ``position`` never
        # changes, so sorting occurrences preserves the required left-to-right
        # non-overlapping replacement order even after earlier merges remove
        # nodes from the list.
        token: list[int] = []
        next_node: list[int] = []
        previous_node: list[int] = []
        active: list[bool] = []
        position: list[int] = []
        document_heads: list[int] = []
        document_tails: list[int] = []
        for data in documents_bytes:
            if not data:
                continue
            head = len(token)
            for index, value in enumerate(data):
                token.append(BYTE_OFFSET + value)
                next_node.append(head + index + 1 if index + 1 < len(data) else -1)
                previous_node.append(head + index - 1 if index else -1)
                active.append(True)
                position.append(index)
            document_heads.append(head)
            document_tails.append(head + len(data) - 1)

        frequencies: collections.Counter[tuple[int, int]] = collections.Counter()
        occurrences: dict[tuple[int, int], set[int]] = collections.defaultdict(set)
        for head in document_heads:
            current = head
            while current != -1:
                right = next_node[current]
                if right != -1:
                    pair = (token[current], token[right])
                    frequencies[pair] += 1
                    occurrences[pair].add(current)
                current = right

        import heapq

        heap: list[tuple[int, int, int]] = [(-count, left, right) for (left, right), count in frequencies.items()]
        heapq.heapify(heap)

        def remove_edge(left_node: int, right_node: int) -> None:
            if left_node == -1 or right_node == -1:
                return
            pair = (token[left_node], token[right_node])
            frequencies[pair] -= 1
            occurrences[pair].discard(left_node)
            heapq.heappush(heap, (-frequencies[pair], pair[0], pair[1]))

        def add_edge(left_node: int, right_node: int) -> None:
            if left_node == -1 or right_node == -1:
                return
            pair = (token[left_node], token[right_node])
            frequencies[pair] += 1
            occurrences[pair].add(left_node)
            heapq.heappush(heap, (-frequencies[pair], pair[0], pair[1]))

        while len(merges) < config.merge_count:
            pair: tuple[int, int] | None = None
            while heap:
                neg_count, left, right = heapq.heappop(heap)
                current_count = frequencies[(left, right)]
                if -neg_count == current_count and current_count > 0:
                    pair = (left, right)
                    break
            if pair is None:
                break
            left, right = pair
            merged_bytes = byte_map[left] + byte_map[right]
            if merged_bytes in byte_representations:
                raise ValueError("training would create a duplicate byte representation")
            merge = Merge(left, right, next_id)
            merges.append(merge)
            byte_map[next_id] = merged_bytes
            byte_representations.add(merged_bytes)

            selected_nodes: list[int] = []
            for node in sorted(occurrences[pair], key=lambda value: (position[value], value)):
                right_node = next_node[node]
                if active[node] and right_node != -1 and active[right_node] and token[node] == left and token[right_node] == right:
                    selected_nodes.append(node)
            for node in selected_nodes:
                right_node = next_node[node]
                if not active[node] or right_node == -1 or not active[right_node] or token[node] != left or token[right_node] != right:
                    continue
                before = previous_node[node]
                after = next_node[right_node]
                remove_edge(before, node)
                remove_edge(node, right_node)
                remove_edge(right_node, after)
                token[node] = next_id
                next_node[node] = after
                if after != -1:
                    previous_node[after] = node
                if before != -1:
                    next_node[before] = node
                active[right_node] = False
                previous_node[right_node] = -1
                next_node[right_node] = -1
                add_edge(before, node)
                add_edge(node, after)
            next_id += 1

        if require_full and len(merges) != config.merge_count:
            raise EncoderError(
                "BLOCKED_TOKENIZER_CORPUS",
                "approved corpus did not yield the complete frozen merge vocabulary",
                {"learned_merges": len(merges), "required_merges": config.merge_count},
            )
        if len(merges) != config.merge_count:
            # A caller may explicitly request a diagnostic partial build. Do
            # not let that artifact claim the frozen deployment vocabulary;
            # its config must describe the actual payload it contains.
            config = dataclasses.replace(config, merge_count=len(merges), vocab_size=FIRST_MERGE_ID + len(merges))
        return cls(merges, config=config)

    def encode(self, text: str) -> list[int]:
        data = _strict_utf8(text)
        if not data:
            return []
        token: list[int] = [BYTE_OFFSET + value for value in data]
        next_node = [index + 1 if index + 1 < len(token) else -1 for index in range(len(token))]
        previous_node = [index - 1 if index else -1 for index in range(len(token))]
        active = [True] * len(token)
        position = list(range(len(token)))
        pair_to_rank = {(merge.left, merge.right): rank for rank, merge in enumerate(self.merges)}
        occurrences: dict[tuple[int, int], set[int]] = collections.defaultdict(set)
        for node in range(len(token) - 1):
            pair = (token[node], token[node + 1])
            if pair in pair_to_rank:
                occurrences[pair].add(node)

        def remove_edge(left_node: int, right_node: int) -> None:
            if left_node == -1 or right_node == -1:
                return
            pair = (token[left_node], token[right_node])
            if pair in pair_to_rank:
                occurrences[pair].discard(left_node)

        def add_edge(left_node: int, right_node: int) -> None:
            if left_node == -1 or right_node == -1:
                return
            pair = (token[left_node], token[right_node])
            if pair in pair_to_rank:
                occurrences[pair].add(left_node)

        # Proposal B applies the ordered merge history one rank at a time.
        # Newly created pairs whose rank has already passed are intentionally
        # left untouched; this is why a generic "merge lowest current pair"
        # loop would not be equivalent.
        for merge in self.merges:
            pair = (merge.left, merge.right)
            selected_nodes: list[int] = []
            for node in sorted(occurrences[pair], key=lambda value: (position[value], value)):
                right_node = next_node[node]
                if active[node] and right_node != -1 and active[right_node] and token[node] == merge.left and token[right_node] == merge.right:
                    selected_nodes.append(node)
            for node in selected_nodes:
                right_node = next_node[node]
                if not active[node] or right_node == -1 or not active[right_node] or token[node] != merge.left or token[right_node] != merge.right:
                    continue
                before = previous_node[node]
                after = next_node[right_node]
                remove_edge(before, node)
                remove_edge(node, right_node)
                remove_edge(right_node, after)
                token[node] = merge.new_id
                next_node[node] = after
                if after != -1:
                    previous_node[after] = node
                if before != -1:
                    next_node[before] = node
                active[right_node] = False
                previous_node[right_node] = -1
                next_node[right_node] = -1
                add_edge(before, node)
                add_edge(node, after)
        sequence: list[int] = []
        node = 0
        while node != -1:
            if active[node]:
                sequence.append(token[node])
            node = next_node[node]
        return sequence

    def decode(self, token_ids: Sequence[int]) -> str:
        try:
            data = b"".join(self._bytes_by_id[token_id] for token_id in token_ids)
        except KeyError as exc:
            raise invalid_input("unknown tokenizer token ID", token_id=exc.args[0]) from exc
        try:
            return data.decode("utf-8", "strict")
        except UnicodeDecodeError as exc:
            raise invalid_input("token sequence is not valid UTF-8", reason=str(exc)) from exc

    def token_bytes(self, token_id: int) -> bytes:
        try:
            return self._bytes_by_id[token_id]
        except KeyError as exc:
            raise invalid_input("unknown tokenizer token ID", token_id=token_id) from exc

    def payload(self) -> dict:
        return {
            "config": dataclasses.asdict(self.config),
            "structural_ids": STRUCTURAL_IDS,
            "vocab": {
                str(token_id): base64.b64encode(value).decode("ascii")
                for token_id, value in sorted(self._bytes_by_id.items())
            },
            "merges": [merge.as_list() for merge in self.merges],
        }

    def identity(self) -> str:
        return sha256_bytes(canonical_json_bytes(self.payload()))

    def save(self, directory: str | Path, *, source_sha: str | None = None, corpus_hash: str | None = None) -> dict:
        destination = Path(directory)
        destination.mkdir(parents=True, exist_ok=True)
        payload = self.payload()
        write_json(destination / "tokenizer.json", payload)
        metadata = {
            "artifact_type": "juniper-tokenizer",
            "payload_sha256": sha256_bytes(canonical_json_bytes(payload)),
            "tokenizer_identity": self.identity(),
            "vocab_size": len(self._bytes_by_id) + len(STRUCTURAL_IDS),
            "source_sha": source_sha,
            "corpus_hash": corpus_hash,
            "implementation_version": self.config.implementation_version,
        }
        write_json(destination / "manifest.json", metadata)
        return metadata

    @classmethod
    def load(cls, directory: str | Path) -> "RawByteBPE":
        import json

        path = Path(directory) / "tokenizer.json"
        payload = json.loads(path.read_text(encoding="utf-8"))
        config = TokenizerConfig(**payload["config"])
        merges = [Merge(*item) for item in payload["merges"]]
        tokenizer = cls(merges, config=config)
        if tokenizer.payload() != payload:
            raise ValueError("tokenizer payload is not canonical or does not round-trip")
        manifest_path = Path(directory) / "manifest.json"
        if manifest_path.exists():
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            expected = sha256_bytes(canonical_json_bytes(payload))
            if manifest.get("payload_sha256") != expected or manifest.get("tokenizer_identity") != tokenizer.identity():
                raise ValueError("tokenizer manifest identity does not match tokenizer payload")
        return tokenizer

    def compare_payload(self, other: "RawByteBPE") -> bool:
        return self.payload() == other.payload()


def ordinary_token_count(tokenizer: RawByteBPE, text: str) -> int:
    return len(tokenizer.encode(text))


def validate_round_trip(tokenizer: RawByteBPE, strings: Iterable[str]) -> None:
    for text in strings:
        token_ids = tokenizer.encode(text)
        decoded = tokenizer.decode(token_ids)
        if decoded != text:
            raise AssertionError("tokenizer full-string round trip failed")
        if any(token_id in STRUCTURAL_IDS.values() for token_id in token_ids):
            raise AssertionError("ordinary content emitted a structural ID")

"""Safe-tensor checkpoints with explicit, validated resume state.

No canonical checkpoint path uses ``torch.save`` or an executable pickle. Model
and optimizer tensors are stored in safetensors; scalar and RNG metadata is
stored as canonical JSON. This makes the resume contract inspectable and keeps
untrusted checkpoint bytes from being imported as Python objects.
"""

from __future__ import annotations

import base64
import dataclasses
import json
import random
from pathlib import Path
from typing import Any

from ..errors import EncoderError
from ..utils import canonical_json_bytes, sha256_bytes, sha256_file, write_json
from .protocol import require_safetensors


@dataclasses.dataclass(frozen=True)
class CheckpointMetadata:
    format_version: str
    source_sha: str
    config_hashes: dict[str, str]
    rng_states: dict[str, Any]
    successful_updates: int
    attempted_updates: int
    skipped_updates: int
    consumed_tokens: int
    sampler_identity: str
    tokenizer_identity: str
    data_identity: str
    predecessor_identity: str | None
    epoch: int = 0
    cursor: int = 0
    batch_state: dict[str, Any] = dataclasses.field(default_factory=dict)
    accumulation_state: dict[str, Any] = dataclasses.field(default_factory=dict)
    precision: dict[str, Any] = dataclasses.field(default_factory=dict)
    kernel_settings: dict[str, Any] = dataclasses.field(default_factory=dict)
    environment_lock_identity: str | None = None

    def payload(self) -> dict[str, Any]:
        return dataclasses.asdict(self)

    def identity(self) -> str:
        return sha256_bytes(canonical_json_bytes(self.payload()))


def validate_checkpoint_metadata(payload: dict[str, Any]) -> dict[str, Any]:
    required = {
        "format_version", "source_sha", "config_hashes", "rng_states", "successful_updates",
        "attempted_updates", "skipped_updates", "consumed_tokens", "sampler_identity",
        "tokenizer_identity", "data_identity", "predecessor_identity",
    }
    missing = sorted(required - set(payload))
    if missing:
        raise EncoderError("INVALID_INPUT", "checkpoint metadata is incomplete", {"missing": missing})
    for field in ("successful_updates", "attempted_updates", "skipped_updates", "consumed_tokens"):
        if not isinstance(payload[field], int) or payload[field] < 0:
            raise EncoderError("INVALID_INPUT", "checkpoint counters must be nonnegative integers", {"field": field})
    if payload["successful_updates"] + payload["skipped_updates"] > payload["attempted_updates"]:
        raise EncoderError("INVALID_INPUT", "checkpoint counters are inconsistent")
    return {"status": "VALID", "identity": sha256_bytes(canonical_json_bytes(payload))}


def _jsonable(value: Any) -> Any:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, (tuple, list)):
        return [_jsonable(item) for item in value]
    if isinstance(value, dict):
        return {str(key): _jsonable(item) for key, item in value.items()}
    if hasattr(value, "tolist"):
        return _jsonable(value.tolist())
    raise TypeError(f"unsupported metadata value {type(value).__name__}")


def _capture_rng() -> dict[str, Any]:
    result: dict[str, Any] = {"python": _jsonable(random.getstate())}
    try:
        import numpy as np

        state = np.random.get_state()
        result["numpy"] = {"algorithm": state[0], "keys": state[1].tolist(), "position": int(state[2]), "has_gauss": int(state[3]), "cached_gaussian": float(state[4])}
    except ImportError:
        result["numpy"] = None
    return result


def _restore_rng(states: dict[str, Any], tensors: dict[str, Any]) -> None:
    if states.get("python") is not None:
        random.setstate(_to_tuple(states["python"]))
    if states.get("numpy") is not None:
        try:
            import numpy as np

            value = states["numpy"]
            np.random.set_state((value["algorithm"], np.asarray(value["keys"], dtype=np.uint32), int(value["position"]), int(value["has_gauss"]), float(value["cached_gaussian"])))
        except ImportError:
            pass
    import torch

    if "rng/cpu" in tensors:
        torch.set_rng_state(tensors["rng/cpu"].cpu())
    if torch.cuda.is_available():
        cuda_states = [tensors[key].cpu() for key in sorted(tensors) if key.startswith("rng/cuda/")]
        if cuda_states:
            torch.cuda.set_rng_state_all(cuda_states)


def _to_tuple(value: Any) -> Any:
    return tuple(_to_tuple(item) for item in value) if isinstance(value, list) else value


def _parameter_names(module: Any) -> dict[Any, str]:
    return {parameter: name for name, parameter in module.named_parameters()}


def save_checkpoint(
    directory: str | Path,
    model: Any,
    optimizer: Any,
    scheduler: Any,
    scaler: Any,
    metadata: CheckpointMetadata,
    *,
    sampler_state: dict[str, Any] | None = None,
    precision: dict[str, Any] | None = None,
) -> dict[str, Any]:
    safe_torch = require_safetensors()
    import torch

    destination = Path(directory)
    destination.mkdir(parents=True, exist_ok=True)
    model_tensors = {name: tensor.detach().cpu().contiguous() for name, tensor in model.state_dict().items() if hasattr(tensor, "detach")}
    safe_torch.save_file(model_tensors, str(destination / "model.safetensors"), metadata={"format": "juniper-model-v2"})

    names = _parameter_names(model)
    optimizer_tensors: dict[str, Any] = {}
    optimizer_entries: list[dict[str, Any]] = []
    for index, (parameter, state) in enumerate(optimizer.state.items()):
        name = names.get(parameter)
        if name is None:
            raise EncoderError("INVALID_INPUT", "optimizer contains a parameter absent from the model")
        entry = {"index": index, "parameter": name, "tensor_keys": []}
        for state_name, value in state.items():
            if hasattr(value, "detach"):
                tensor_key = f"optimizer/{index}/{state_name}"
                optimizer_tensors[tensor_key] = value.detach().cpu().contiguous()
                entry["tensor_keys"].append(tensor_key)
            else:
                entry.setdefault("scalars", {})[state_name] = _jsonable(value)
        optimizer_entries.append(entry)
    if optimizer_tensors:
        safe_torch.save_file(optimizer_tensors, str(destination / "optimizer.safetensors"), metadata={"format": "juniper-optimizer-v2"})

    rng_tensors = {"rng/cpu": torch.get_rng_state().cpu()}
    if torch.cuda.is_available():
        rng_tensors.update({f"rng/cuda/{index}": state.cpu() for index, state in enumerate(torch.cuda.get_rng_state_all())})
    safe_torch.save_file(rng_tensors, str(destination / "rng.safetensors"), metadata={"format": "juniper-rng-v2"})

    payload = metadata.payload()
    payload["rng_states"] = _capture_rng()
    payload["sampler_state"] = sampler_state or {}
    payload["precision"] = precision or payload.get("precision", {})
    payload["optimizer_entries"] = optimizer_entries
    payload["scheduler_state"] = _jsonable(scheduler.state_dict()) if scheduler is not None else None
    payload["scaler_state"] = _jsonable(scaler.state_dict()) if scaler is not None else None
    payload["weights_sha256"] = sha256_file(destination / "model.safetensors")
    payload["optimizer_sha256"] = sha256_file(destination / "optimizer.safetensors") if optimizer_tensors else None
    payload["rng_sha256"] = sha256_file(destination / "rng.safetensors")
    validation = validate_checkpoint_metadata(payload)
    result = {"metadata": payload, "checkpoint_identity": validation["identity"], "weights_format": "safetensors", "directory": destination.as_posix()}
    write_json(destination / "metadata.json", result)
    return result


def load_checkpoint(directory: str | Path, model: Any, optimizer: Any | None = None, scheduler: Any | None = None, scaler: Any | None = None, *, restore_rng: bool = True) -> dict[str, Any]:
    safe_torch = require_safetensors()
    import torch

    source = Path(directory)
    wrapper = json.loads((source / "metadata.json").read_text(encoding="utf-8"))
    payload = wrapper.get("metadata", wrapper)
    validate_checkpoint_metadata(payload)
    if payload.get("weights_sha256") != sha256_file(source / "model.safetensors"):
        raise EncoderError("INVALID_INPUT", "checkpoint model tensor checksum mismatch")
    model.load_state_dict(safe_torch.load_file(str(source / "model.safetensors"), device="cpu"), strict=True)
    if optimizer is not None and (source / "optimizer.safetensors").exists():
        tensors = safe_torch.load_file(str(source / "optimizer.safetensors"), device="cpu")
        names = _parameter_names(model)
        by_name = {name: parameter for parameter, name in names.items()}
        optimizer.state.clear()
        for entry in payload.get("optimizer_entries", []):
            parameter = by_name.get(entry["parameter"])
            if parameter is None:
                raise EncoderError("INVALID_INPUT", "checkpoint optimizer parameter is absent from model", {"parameter": entry["parameter"]})
            state: dict[str, Any] = {key.rsplit("/", 1)[-1]: tensors[key].to(parameter.device) for key in entry.get("tensor_keys", [])}
            state.update(entry.get("scalars", {}))
            optimizer.state[parameter] = state
    if scheduler is not None and payload.get("scheduler_state") is not None:
        scheduler.load_state_dict(payload["scheduler_state"])
    if scaler is not None and payload.get("scaler_state") is not None:
        scaler.load_state_dict(payload["scaler_state"])
    if restore_rng and (source / "rng.safetensors").exists():
        _restore_rng(payload.get("rng_states", {}), safe_torch.load_file(str(source / "rng.safetensors"), device="cpu"))
    return {"status": "LOADED", "checkpoint_identity": wrapper.get("checkpoint_identity"), "metadata": payload}


def write_metadata(path: str | Path, metadata: CheckpointMetadata) -> dict[str, Any]:
    payload = metadata.payload()
    result = {"metadata": payload, "checkpoint_identity": metadata.identity(), "weights_format": "safetensors"}
    write_json(path, result)
    return result

"""Resolved training protocol; expensive execution is never silently faked."""

from __future__ import annotations

import dataclasses
import random
from typing import Any, Sequence

from ..constants import ORDINARY_TOKEN_MIN, ORDINARY_TOKEN_MAX
from ..errors import EncoderError
from ..utils import canonical_json_bytes, sha256_bytes


@dataclasses.dataclass(frozen=True)
class MaskingProtocol:
    seed: int = 1729
    mask_rate: float = 0.15

    def mask(self, token_ids: Sequence[int], example_id: str, epoch: int) -> tuple[list[int], list[int]]:
        masked, positions, targets = self.mask_detailed(token_ids, example_id, epoch)
        return masked, targets

    def mask_detailed(self, token_ids: Sequence[int], example_id: str, epoch: int) -> tuple[list[int], list[int], list[int]]:
        """Apply deterministic 80/10/10 MLM corruption and return positions.

        Structural IDs and PAD are never selected. The per-example RNG makes
        masking independent of worker scheduling and the fallback guarantees a
        nonempty target set whenever ordinary tokens exist.
        """
        eligible = [i for i, token_id in enumerate(token_ids) if ORDINARY_TOKEN_MIN <= token_id <= ORDINARY_TOKEN_MAX]
        rng = random.Random(f"{self.seed}:{example_id}:{epoch}")
        chosen = [i for i in eligible if rng.random() < self.mask_rate]
        if eligible and not chosen:
            chosen = [eligible[0]]
        output = list(token_ids)
        positions: list[int] = []
        targets: list[int] = []
        for position in chosen:
            positions.append(position)
            targets.append(token_ids[position])
            branch = rng.random()
            if branch < 0.8:
                output[position] = 4
            elif branch < 0.9:
                output[position] = rng.randint(ORDINARY_TOKEN_MIN, ORDINARY_TOKEN_MAX)
        return output, positions, targets


@dataclasses.dataclass(frozen=True)
class ResolvedProtocol:
    stage: str
    seed: int
    max_consumed_tokens: int
    successful_update_budget: int | None
    config_hash: str
    workers: int = 0

    @classmethod
    def from_config(cls, stage: str, config: dict[str, Any]) -> "ResolvedProtocol":
        if config.get("workers", 0) != 0:
            raise ValueError("reference protocol starts with zero data-loader workers")
        payload = {"stage": stage, "config": config}
        return cls(stage, int(config.get("seed", 1729)), int(config.get("max_consumed_tokens", 0)), config.get("successful_update_budget"), sha256_bytes(canonical_json_bytes(payload)), 0)


def require_training_runtime() -> None:
    try:
        import torch
    except ImportError as exc:
        raise EncoderError("BLOCKED_ENVIRONMENT", "training requires the verified PyTorch runtime", {"dependency": "torch"}) from exc
    if not hasattr(torch, "optim"):
        raise EncoderError("BLOCKED_ENVIRONMENT", "PyTorch optimizer support is unavailable")


def require_safetensors() -> Any:
    try:
        from safetensors import torch as safe_torch
    except ImportError as exc:
        raise EncoderError("BLOCKED_ENVIRONMENT", "safe tensor serialization is required for training checkpoints", {"dependency": "safetensors"}) from exc
    return safe_torch


def run_mechanical_smoke(config: dict[str, Any]) -> dict[str, Any]:
    """Run a real finite forward/backward check when the verified runtime exists."""
    require_training_runtime()
    import torch
    from ..model import DeploymentModel, actual_parameter_counts

    torch.manual_seed(int(config.get("seed", 1729)))
    model = DeploymentModel(seed=int(config.get("seed", 1729)))
    model.train()
    input_ids = torch.tensor([[7, 8, 9, 0], [10, 11, 0, 0]], dtype=torch.long)
    vectors = model.retrieval_vector(input_ids)
    loss = vectors.float().square().mean()
    loss.backward()
    pad_grad = model.backbone.embedding.weight.grad[0].abs().max().item()
    model.backbone.enforce_pad_row()
    finite = bool(torch.isfinite(loss)) and bool(torch.isfinite(vectors).all()) and bool(torch.isfinite(model.backbone.embedding.weight.grad).all())
    if not finite or pad_grad != 0.0:
        raise EncoderError("NUMERICAL_ERROR", "mechanical smoke produced nonfinite values or a PAD gradient")
    return {"status": "SMOKE_TESTED", "loss": float(loss.item()), "pad_gradient_max_abs": pad_grad, "counts": actual_parameter_counts(model)}

"""Small dependency-free helpers used for identity and safe serialization."""

from __future__ import annotations

import hashlib
import json
import math
import os
import tempfile
from pathlib import Path
from typing import Any, Iterable

from .errors import numerical_error


def canonical_json_bytes(value: Any) -> bytes:
    """The single JSON convention used for all semantic payloads."""
    try:
        text = json.dumps(
            value,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=False,
            separators=(",", ":"),
        )
    except (TypeError, ValueError) as exc:
        raise ValueError(f"value is not canonical JSON: {exc}") from exc
    return text.encode("utf-8", "strict")


def strict_json_loads(text: str | bytes) -> Any:
    def hook(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f"duplicate JSON key: {key}")
            result[key] = value
        return result

    return json.loads(text, object_pairs_hook=hook, parse_constant=lambda x: (_ for _ in ()).throw(ValueError(x)))


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: str | os.PathLike[str]) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def sha256_tree(root: str | os.PathLike[str], *, exclude: Iterable[str] = ()) -> dict[str, str]:
    root_path = Path(root)
    excluded = set(exclude)
    result: dict[str, str] = {}
    for path in sorted(p for p in root_path.rglob("*") if p.is_file()):
        relative = path.relative_to(root_path).as_posix()
        if relative not in excluded:
            result[relative] = sha256_file(path)
    return result


def atomic_write_bytes(path: str | os.PathLike[str], data: bytes) -> None:
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=f".{destination.name}.", dir=destination.parent)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise


def require_finite(values: Iterable[float], label: str) -> None:
    for index, value in enumerate(values):
        if not math.isfinite(float(value)):
            raise numerical_error(f"nonfinite {label}", index=index, value=repr(value))


def load_config(path: str | os.PathLike[str]) -> dict[str, Any]:
    """Load JSON-compatible YAML files without silently accepting loose syntax."""
    raw = Path(path).read_text(encoding="utf-8")
    try:
        value = strict_json_loads(raw)
    except (ValueError, json.JSONDecodeError):
        try:
            import yaml  # type: ignore
        except ImportError as exc:
            raise ValueError(f"{path} is not JSON and PyYAML is not installed") from exc
        value = yaml.safe_load(raw)
    if not isinstance(value, dict):
        raise ValueError(f"config {path} must contain an object")
    return value


def write_json(path: str | os.PathLike[str], value: Any) -> None:
    atomic_write_bytes(path, canonical_json_bytes(value) + b"\n")
